library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity alu is
  port (
    a_in      : in  std_logic_vector(7 downto 0);
    b_in      : in  std_logic_vector(7 downto 0);
    clk       : in  std_logic;
    carry_out : out std_logic;
    fi_en     : in  std_logic;
    rst       : in  std_logic;
    result_out : out std_logic_vector(7 downto 0);
    sub       : in  std_logic;
    zero_out  : out std_logic
  );
end entity alu;

architecture rtl of alu is
  signal sum9       : unsigned(8 downto 0);
  signal carry_comb : std_logic;
  signal zero_comb  : std_logic;
  signal flag_c     : std_logic := '0';
  signal flag_z     : std_logic := '0';
begin

  p_comb: process(all)
    variable a9 : unsigned(8 downto 0);
    variable b9 : unsigned(8 downto 0);
  begin
    a9 := '0' & unsigned(a_in);
    if sub = '1' then
      b9 := ('0' & unsigned(not b_in)) + to_unsigned(1, 9);
    else
      b9 := '0' & unsigned(b_in);
    end if;
    sum9 <= a9 + b9;
  end process p_comb;

  carry_comb <= sum9(8);
  zero_comb  <= '1' when sum9(7 downto 0) = to_unsigned(0, 8) else '0';

  result_out <= std_logic_vector(sum9(7 downto 0));

  p_flags: process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        flag_c <= '0';
        flag_z <= '0';
      elsif fi_en = '1' then
        flag_c <= carry_comb;
        flag_z <= zero_comb;
      end if;
    end if;
  end process p_flags;

  carry_out <= flag_c;
  zero_out  <= flag_z;

end architecture rtl;

sources.src/ben_eater_cpu.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity ben_eater_cpu is
  generic (
    TICK_CYCLES     : positive := 4000000;
    DEBOUNCE_CYCLES : positive := 1000000;
    CLKS_PER_BIT    : positive := 868
  );
  port (
    clk      : in  std_logic;
    rst      : in  std_logic;
    btn_step : in  std_logic;
    sw       : in  std_logic_vector(3 downto 0);
    led      : out std_logic_vector(3 downto 0);
    uart_rx  : in  std_logic;
    uart_tx  : out std_logic
  );
end entity ben_eater_cpu;

architecture rtl of ben_eater_cpu is
  -- Synchronisierte Eingaenge
  signal sw_sync_vec   : std_logic_vector(3 downto 0);
  signal btn_in_vec    : std_logic_vector(0 downto 0);
  signal btn_sync_vec  : std_logic_vector(0 downto 0);
  signal btn_synced    : std_logic;
  signal rx_in_vec     : std_logic_vector(0 downto 0);
  signal rx_sync_vec   : std_logic_vector(0 downto 0);
  signal uart_synced   : std_logic;

  -- Entpreller / Takt
  signal db_rise       : std_logic;
  signal db_dout       : std_logic;
  signal step_enable   : std_logic;

  -- Steuerwerk
  signal s_ai      : std_logic;
  signal s_ao      : std_logic;
  signal s_bi      : std_logic;
  signal s_ce      : std_logic;
  signal s_co      : std_logic;
  signal s_eo      : std_logic;
  signal s_fi      : std_logic;
  signal s_hlt     : std_logic;
  signal s_ii      : std_logic;
  signal s_io      : std_logic;
  signal s_ri      : std_logic;
  signal s_ro      : std_logic;
  signal s_su      : std_logic;
  signal s_j       : std_logic;
  signal s_mi      : std_logic;
  signal s_oi      : std_logic;
  signal s_halted  : std_logic;

  -- Gegatete Freigaben (nur bei step_enable wirksam)
  signal ce_g : std_logic;
  signal j_g  : std_logic;
  signal mi_g : std_logic;
  signal ri_g : std_logic;
  signal ai_g : std_logic;
  signal bi_g : std_logic;
  signal oi_g : std_logic;
  signal ii_g : std_logic;
  signal fi_g : std_logic;

  -- Datenpfad
  signal bus_sig     : std_logic_vector(7 downto 0);
  signal pc_val      : std_logic_vector(3 downto 0);
  signal ram_out_sig : std_logic_vector(7 downto 0);
  signal ir_val      : std_logic_vector(7 downto 0);
  signal a_val       : std_logic_vector(7 downto 0);
  signal b_val       : std_logic_vector(7 downto 0);
  signal out_val     : std_logic_vector(7 downto 0);
  signal alu_res     : std_logic_vector(7 downto 0);
  signal flag_c      : std_logic;
  signal flag_z      : std_logic;

  -- UART / Lader
  signal rx_data_sig    : std_logic_vector(7 downto 0);
  signal rx_valid_sig   : std_logic;
  signal loader_busy    : std_logic;
  signal prog_data_sig  : std_logic_vector(127 downto 0);
  signal prog_valid_sig : std_logic;
  signal uart_mode_sig  : std_logic;
  signal tx_busy_sig    : std_logic;
  signal tx_send_en     : std_logic;

  -- CPU-Clear bei UART-Rahmen (rst oder prog_valid)
  signal cpu_rst : std_logic;
begin

  cpu_rst <= rst or prog_valid_sig;

  -- Eingangssynchronisierer (laufen immer, kein Reset)
  btn_in_vec(0) <= btn_step;
  rx_in_vec(0)  <= uart_rx;

  u_sw_sync: entity work.input_sync
    generic map (
      INIT  => 0,
      WIDTH => 4
    )
    port map (
      clk      => clk,
      data_in  => sw,
      data_out => sw_sync_vec
    );

  u_btn_sync: entity work.input_sync
    generic map (
      INIT  => 0,
      WIDTH => 1
    )
    port map (
      clk      => clk,
      data_in  => btn_in_vec,
      data_out => btn_sync_vec
    );

  u_rx_sync: entity work.input_sync
    generic map (
      INIT  => 1,
      WIDTH => 1
    )
    port map (
      clk      => clk,
      data_in  => rx_in_vec,
      data_out => rx_sync_vec
    );

  btn_synced  <= btn_sync_vec(0);
  uart_synced <= rx_sync_vec(0);

  u_deb: entity work.debouncer
    generic map (
      DEBOUNCE_CYCLES => DEBOUNCE_CYCLES
    )
    port map (
      clk  => clk,
      rst  => rst,
      din  => btn_synced,
      dout => db_dout,
      rise => db_rise
    );

  u_clk: entity work.clock_ctrl
    generic map (
      TICK_CYCLES => TICK_CYCLES
    )
    port map (
      clk         => clk,
      halted      => s_halted,
      loader_busy => loader_busy,
      oi_active   => s_oi,
      rst         => rst,
      step_rise   => db_rise,
      sw_step     => sw_sync_vec(1),
      tx_busy     => tx_busy_sig,
      uart_mode   => uart_mode_sig,
      step_enable => step_enable,
      tick        => open
    );

  u_ctrl: entity work.control_unit
    port map (
      ai          => s_ai,
      ao          => s_ao,
      bi          => s_bi,
      ce          => s_ce,
      clear       => prog_valid_sig,
      clk         => clk,
      co          => s_co,
      eo          => s_eo,
      fi          => s_fi,
      flag_c      => flag_c,
      flag_z      => flag_z,
      halted      => s_halted,
      hlt         => s_hlt,
      ii          => s_ii,
      io          => s_io,
      opcode      => ir_val(7 downto 4),
      ri          => s_ri,
      ro          => s_ro,
      rst         => rst,
      step_enable => step_enable,
      su          => s_su,
      j_load      => s_j,
      mi          => s_mi,
      oi          => s_oi
    );

  -- Freigaben gelten nur im ausgefuehrten Mikroschritt
  ce_g <= s_ce and step_enable;
  j_g  <= s_j and step_enable;
  mi_g <= s_mi and step_enable;
  ri_g <= s_ri and step_enable;
  ai_g <= s_ai and step_enable;
  bi_g <= s_bi and step_enable;
  oi_g <= s_oi and step_enable;
  ii_g <= s_ii and step_enable;
  fi_g <= s_fi and step_enable;

  -- Bus-Multiplexer (keine Tri-State)
  p_bus: process(all)
  begin
    if s_co = '1' then
      bus_sig <= "0000" & pc_val;
    elsif s_ro = '1' then
      bus_sig <= ram_out_sig;
    elsif s_io = '1' then
      bus_sig <= "0000" & ir_val(3 downto 0);
    elsif s_ao = '1' then
      bus_sig <= a_val;
    elsif s_eo = '1' then
      bus_sig <= alu_res;
    else
      bus_sig <= (others => '0');
    end if;
  end process p_bus;

  u_pc: entity work.program_counter
    port map (
      ce        => ce_g,
      clk       => clk,
      data_in   => bus_sig(3 downto 0),
      j_load    => j_g,
      rst       => cpu_rst,
      count_out => pc_val
    );

  u_mem: entity work.memory
    port map (
      addr_in    => bus_sig(3 downto 0),
      clk        => clk,
      data_in    => bus_sig,
      mi_en      => mi_g,
      prog_data  => prog_data_sig,
      prog_sel   => sw_sync_vec(3 downto 2),
      prog_valid => prog_valid_sig,
      ram_out    => ram_out_sig,
      ri_en      => ri_g,
      rst        => rst
    );

  u_reg_a: entity work.register8
    port map (
      clk      => clk,
      data_in  => bus_sig,
      data_out => a_val,
      load_en  => ai_g,
      rst      => cpu_rst
    );

  u_reg_b: entity work.register8
    port map (
      clk      => clk,
      data_in  => bus_sig,
      data_out => b_val,
      load_en  => bi_g,
      rst      => cpu_rst
    );

  u_reg_out: entity work.register8
    port map (
      clk      => clk,
      data_in  => bus_sig,
      data_out => out_val,
      load_en  => oi_g,
      rst      => cpu_rst
    );

  u_reg_ir: entity work.register8
    port map (
      clk      => clk,
      data_in  => bus_sig,
      data_out => ir_val,
      load_en  => ii_g,
      rst      => cpu_rst
    );

  u_alu: entity work.alu
    port map (
      a_in       => a_val,
      b_in       => b_val,
      clk        => clk,
      carry_out  => flag_c,
      fi_en      => fi_g,
      rst        => cpu_rst,
      result_out => alu_res,
      sub        => s_su,
      zero_out   => flag_z
    );

  u_rxe: entity work.uart_rx
    generic map (
      CLKS_PER_BIT => CLKS_PER_BIT
    )
    port map (
      clk        => clk,
      rst        => rst,
      rx_in      => uart_synced,
      data_out   => rx_data_sig,
      data_valid => rx_valid_sig
    );

  u_loader: entity work.loader
    port map (
      clk         => clk,
      rst         => rst,
      rx_data     => rx_data_sig,
      rx_valid    => rx_valid_sig,
      loader_busy => loader_busy,
      prog_data   => prog_data_sig,
      prog_valid  => prog_valid_sig,
      uart_mode   => uart_mode_sig
    );

  -- Im UART-Modus sendet jeder ausgefuehrte OI-Mikroschritt den neuen
  -- OUT-Wert (Bus). Im Board-Modus bleibt send_en '0', uart_tx '1'.
  tx_send_en <= uart_mode_sig and s_oi and step_enable;

  u_txe: entity work.uart_tx
    generic map (
      CLKS_PER_BIT => CLKS_PER_BIT
    )
    port map (
      clk     => clk,
      data_in => bus_sig,
      rst     => rst,
      send_en => tx_send_en,
      busy    => tx_busy_sig,
      tx_out  => uart_tx
    );

  -- LED-Register: jeden Takt das per sw(0) gewaehlte Halbbyte von OUT
  p_led: process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        led <= (others => '0');
      else
        if sw_sync_vec(0) = '0' then
          led <= out_val(3 downto 0);
        else
          led <= out_val(7 downto 4);
        end if;
      end if;
    end if;
  end process p_led;

end architecture rtl;

sources.src/clock_ctrl.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity clock_ctrl is
  generic (
    TICK_CYCLES : positive := 4000000
  );
  port (
    clk         : in  std_logic;
    halted      : in  std_logic;
    loader_busy : in  std_logic;
    oi_active   : in  std_logic;
    rst         : in  std_logic;
    step_rise   : in  std_logic;
    sw_step     : in  std_logic;
    tx_busy     : in  std_logic;
    uart_mode   : in  std_logic;
    step_enable : out std_logic;
    tick        : out std_logic
  );
end entity clock_ctrl;

architecture rtl of clock_ctrl is
  signal cnt    : integer range 0 to 2147483647 := 0;
  signal tick_i : std_logic := '0';
begin
  -- Tick-Generator: zaehlt 0 .. TICK_CYCLES-1, Tick beim Endstand.
  -- Laeuft immer (auch bei Halt), nur synchroner Reset setzt zurueck.
  p_tick : process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        cnt <= 0;
      else
        if cnt = TICK_CYCLES - 1 then
          cnt <= 0;
        else
          cnt <= cnt + 1;
        end if;
      end if;
    end if;
  end process p_tick;

  tick_i <= '1' when cnt = TICK_CYCLES - 1 else '0';
  tick   <= tick_i;

  -- Schrittfreigabe (kombinatorisch, vollstaendig abgedeckt):
  -- Board-Modus: Tick wenn sw_step = '0', step_rise wenn sw_step = '1'.
  -- UART-Modus: jeder Takt, ausser Lader empfängt (loader_busy) oder
  -- OI aktiv waehrend Sender beschaeftigt (oi_active und tx_busy).
  -- In beiden Modi keine Freigabe bei halted = '1'.
  p_step : process(all)
  begin
    if halted = '1' then
      step_enable <= '0';
    elsif uart_mode = '1' then
      if loader_busy = '1' then
        step_enable <= '0';
      elsif oi_active = '1' and tx_busy = '1' then
        step_enable <= '0';
      else
        step_enable <= '1';
      end if;
    else
      if sw_step = '0' then
        step_enable <= tick_i;
      else
        step_enable <= step_rise;
      end if;
    end if;
  end process p_step;

end architecture rtl;

sources.src/control_unit.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity control_unit is
  port (
    ai          : out std_logic;
    ao          : out std_logic;
    bi          : out std_logic;
    ce          : out std_logic;
    clear       : in  std_logic;
    clk         : in  std_logic;
    co          : out std_logic;
    eo          : out std_logic;
    fi          : out std_logic;
    flag_c      : in  std_logic;
    flag_z      : in  std_logic;
    halted      : out std_logic;
    hlt         : out std_logic;
    ii          : out std_logic;
    io          : out std_logic;
    opcode      : in  std_logic_vector(3 downto 0);
    ri          : out std_logic;
    ro          : out std_logic;
    rst         : in  std_logic;
    step_enable : in  std_logic;
    su          : out std_logic;
    j_load      : out std_logic;
    mi          : out std_logic;
    oi          : out std_logic
  );
end entity control_unit;

architecture rtl of control_unit is
  type t_state_t is (T0, T1, T2, T3, T4);
  signal t_state    : t_state_t;
  signal halted_reg : std_logic;
begin

  halted <= halted_reg;

  p_seq: process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' or clear = '1' then
        t_state    <= T0;
        halted_reg <= '0';
      elsif halted_reg = '1' then
        null;
      elsif step_enable = '1' then
        if t_state = T2 and opcode = "1111" then
          halted_reg <= '1';
        else
          case t_state is
            when T0 => t_state <= T1;
            when T1 => t_state <= T2;
            when T2 => t_state <= T3;
            when T3 => t_state <= T4;
            when T4 => t_state <= T0;
          end case;
        end if;
      end if;
    end if;
  end process p_seq;

  p_comb: process(all)
  begin
    ai     <= '0';
    ao     <= '0';
    bi     <= '0';
    ce     <= '0';
    co     <= '0';
    eo     <= '0';
    fi     <= '0';
    hlt    <= '0';
    ii     <= '0';
    io     <= '0';
    ri     <= '0';
    ro     <= '0';
    su     <= '0';
    j_load <= '0';
    mi     <= '0';
    oi     <= '0';

    case t_state is
      when T0 =>
        mi <= '1';
        co <= '1';
      when T1 =>
        ro <= '1';
        ii <= '1';
        ce <= '1';
      when T2 =>
        case opcode is
          when "0001" | "0010" | "0011" | "0100" =>
            io <= '1';
            mi <= '1';
          when "0101" =>
            io <= '1';
            ai <= '1';
          when "0110" =>
            io     <= '1';
            j_load <= '1';
          when "0111" =>
            if flag_c = '1' then
              io     <= '1';
              j_load <= '1';
            end if;
          when "1000" =>
            if flag_z = '1' then
              io     <= '1';
              j_load <= '1';
            end if;
          when "1110" =>
            ao <= '1';
            oi <= '1';
          when "1111" =>
            hlt <= '1';
          when others =>
            null;
        end case;
      when T3 =>
        case opcode is
          when "0001" =>
            ro <= '1';
            ai <= '1';
          when "0010" | "0011" =>
            ro <= '1';
            bi <= '1';
          when "0100" =>
            ao <= '1';
            ri <= '1';
          when others =>
            null;
        end case;
      when T4 =>
        case opcode is
          when "0010" =>
            eo <= '1';
            ai <= '1';
            fi <= '1';
          when "0011" =>
            eo <= '1';
            ai <= '1';
            su <= '1';
            fi <= '1';
          when others =>
            null;
        end case;
    end case;
  end process p_comb;

end architecture rtl;

sources.src/debouncer.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity debouncer is
  generic (
    DEBOUNCE_CYCLES : positive := 1000000
  );
  port (
    clk  : in  std_logic;
    rst  : in  std_logic;
    din  : in  std_logic;
    dout : out std_logic;
    rise : out std_logic
  );
end entity debouncer;

architecture rtl of debouncer is
  signal r_dout : std_logic := '0';
  signal r_rise : std_logic := '0';
  signal cnt    : natural range 0 to 2147483647 := 0;
begin

  dout <= r_dout;
  rise <= r_rise;

  p_seq : process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        r_dout <= '0';
        r_rise <= '0';
        cnt    <= 0;
      else
        if din = r_dout then
          cnt    <= 0;
          r_rise <= '0';
        else
          if cnt = DEBOUNCE_CYCLES - 1 then
            cnt <= 0;
            if r_dout = '0' then
              -- din muss hier '1' sein (din /= dout)
              r_dout <= din;
              r_rise <= '1';
            else
              r_dout <= din;
              r_rise <= '0';
            end if;
          else
            cnt    <= cnt + 1;
            r_rise <= '0';
          end if;
        end if;
      end if;
    end if;
  end process p_seq;

end architecture rtl;

sources.src/input_sync.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity input_sync is
  generic (
    INIT  : integer := 0;
    WIDTH : integer := 1
  );
  port (
    clk      : in  std_logic;
    data_in  : in  std_logic_vector(WIDTH - 1 downto 0);
    data_out : out std_logic_vector(WIDTH - 1 downto 0)
  );
end entity input_sync;

architecture rtl of input_sync is
  constant C_INIT : std_logic_vector(WIDTH - 1 downto 0) :=
    std_logic_vector(to_unsigned(INIT, WIDTH));
  signal sync1 : std_logic_vector(WIDTH - 1 downto 0) := C_INIT;
  signal sync2 : std_logic_vector(WIDTH - 1 downto 0) := C_INIT;
begin

  p_sync : process(clk)
  begin
    if rising_edge(clk) then
      sync1 <= data_in;
      sync2 <= sync1;
    end if;
  end process p_sync;

  data_out <= sync2;

end architecture rtl;

sources.src/loader.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity loader is
  port (
    clk         : in  std_logic;
    rst         : in  std_logic;
    rx_data     : in  std_logic_vector(7 downto 0);
    rx_valid    : in  std_logic;
    loader_busy : out std_logic;
    prog_data   : out std_logic_vector(127 downto 0);
    prog_valid  : out std_logic;
    uart_mode   : out std_logic
  );
end entity loader;

architecture rtl of loader is

  type state_t is (S_IDLE, S_LEN, S_PROG, S_TRAIL, S_DONE);

  type buf_t is array (0 to 15) of std_logic_vector(7 downto 0);
  type trail_t is array (0 to 5) of std_logic_vector(7 downto 0);

  constant TRAIL_ROM : trail_t := (
    x"53", x"54", x"41", x"52", x"54", x"0A"
  );

  constant ZERO_BYTE : std_logic_vector(7 downto 0) := (others => '0');

  signal state         : state_t := S_IDLE;
  signal len_b0        : std_logic_vector(7 downto 0) := (others => '0');
  signal len_b1        : std_logic_vector(7 downto 0) := (others => '0');
  signal len_b2        : std_logic_vector(7 downto 0) := (others => '0');
  signal len_cnt       : integer range 0 to 4 := 0;
  signal frame_len     : integer range 0 to 16 := 0;
  signal prog_cnt      : integer range 0 to 16 := 0;
  signal trail_cnt     : integer range 0 to 6 := 0;
  signal buf           : buf_t := (others => ZERO_BYTE);
  signal uart_mode_reg : std_logic := '0';

begin

  -- Programmpuffer auf prog_data abbilden (statische Slices).
  -- Konvention wie in memory.vhd: RAM(i) = prog_data(8*i+7 downto 8*i).
  g_map : for i in 0 to 15 generate
    prog_data(8 * i + 7 downto 8 * i) <= buf(i);
  end generate g_map;

  uart_mode <= uart_mode_reg;

  -- prog_valid genau einen Takt in S_DONE (Moore).
  prog_valid <= '1' when state = S_DONE else '0';

  -- loader_busy: '1' solange ein Rahmen empfangen wird (Mitte eines Rahmens
  -- oder S_DONE), sowie im selben Takt wie das erste Laengenbyte in S_IDLE,
  -- damit die CPU im UART-Modus sofort anhaelt. In S_IDLE ohne rx_valid '0'.
  p_busy : process(all)
  begin
    if state = S_IDLE and rx_valid = '0' then
      loader_busy <= '0';
    else
      loader_busy <= '1';
    end if;
  end process p_busy;

  p_seq : process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        state         <= S_IDLE;
        len_b0        <= (others => '0');
        len_b1        <= (others => '0');
        len_b2        <= (others => '0');
        len_cnt       <= 0;
        frame_len     <= 0;
        prog_cnt      <= 0;
        trail_cnt     <= 0;
        buf           <= (others => ZERO_BYTE);
        uart_mode_reg <= '0';
      else
        case state is

          when S_IDLE =>
            if rx_valid = '1' then
              len_b0  <= rx_data;
              len_cnt <= 1;
              state   <= S_LEN;
            end if;

          when S_LEN =>
            if rx_valid = '1' then
              if len_cnt = 1 then
                len_b1  <= rx_data;
                len_cnt <= 2;
              elsif len_cnt = 2 then
                len_b2  <= rx_data;
                len_cnt <= 3;
              elsif len_cnt = 3 then
                -- Viertes Laengenbyte ist rx_data (b3). Little endian:
                -- n = b0 + 256*b1 + 65536*b2 + 16777216*b3.
                -- Gueltig genau dann, wenn b1=b2=b3=0 und b0 in 1..16.
                if len_b1 = ZERO_BYTE and len_b2 = ZERO_BYTE
                   and rx_data = ZERO_BYTE
                   and unsigned(len_b0) >= to_unsigned(1, 8)
                   and unsigned(len_b0) <= to_unsigned(16, 8) then
                  frame_len <= to_integer(unsigned(len_b0));
                  prog_cnt  <= 0;
                  trail_cnt <= 0;
                  buf       <= (others => ZERO_BYTE);
                  state     <= S_PROG;
                else
                  len_cnt <= 0;
                  state   <= S_IDLE;
                end if;
              else
                len_cnt <= 0;
                state   <= S_IDLE;
              end if;
            end if;

          when S_PROG =>
            if rx_valid = '1' then
              buf(prog_cnt) <= rx_data;
              if prog_cnt + 1 = frame_len then
                trail_cnt <= 0;
                state     <= S_TRAIL;
              else
                prog_cnt <= prog_cnt + 1;
              end if;
            end if;

          when S_TRAIL =>
            if rx_valid = '1' then
              if rx_data /= TRAIL_ROM(trail_cnt) then
                -- Falsches START-Zeichen: Rahmen verwerfen, naechstes Byte
                -- ist wieder erstes Laengenbyte.
                len_cnt   <= 0;
                prog_cnt  <= 0;
                trail_cnt <= 0;
                state     <= S_IDLE;
              elsif trail_cnt = 5 then
                -- Letztes Zeichen 0A korrekt: Rahmen vollstaendig.
                uart_mode_reg <= '1';
                len_cnt       <= 0;
                prog_cnt      <= 0;
                trail_cnt     <= 0;
                state         <= S_DONE;
              else
                trail_cnt <= trail_cnt + 1;
              end if;
            end if;

          when S_DONE =>
            -- Genau einen Takt prog_valid='1' und busy='1' halten, damit
            -- memory/top die RAM-Uebernahme und das CPU-Clear im Folgetakt
            -- ausfuehren; danach in IDLE (bzw. neuer Rahmen bei rx_valid).
            if rx_valid = '1' then
              len_b0  <= rx_data;
              len_cnt <= 1;
              state   <= S_LEN;
            else
              state <= S_IDLE;
            end if;

          when others =>
            state <= S_IDLE;

        end case;
      end if;
    end if;
  end process p_seq;

end architecture rtl;

sources.src/memory.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity memory is
  port (
    addr_in    : in  std_logic_vector(3 downto 0);
    clk        : in  std_logic;
    data_in    : in  std_logic_vector(7 downto 0);
    mi_en      : in  std_logic;
    prog_data  : in  std_logic_vector(127 downto 0);
    prog_sel   : in  std_logic_vector(1 downto 0);
    prog_valid : in  std_logic;
    ram_out    : out std_logic_vector(7 downto 0);
    ri_en      : in  std_logic;
    rst        : in  std_logic
  );
end entity memory;

architecture rtl of memory is

  type ram_t is array (0 to 15) of std_logic_vector(7 downto 0);

  -- Feste Programme nach PROMPT.md, Adresse 0 .. 15.
  constant PROG_00 : ram_t := (
    x"51", x"4E", x"50", x"E0", x"2E", x"4F", x"1E", x"4D",
    x"1F", x"4E", x"1D", x"70", x"63", x"00", x"00", x"00"
  );
  constant PROG_01 : ram_t := (
    x"E0", x"2F", x"74", x"60", x"3F", x"E0", x"80", x"64",
    x"00", x"00", x"00", x"00", x"00", x"00", x"00", x"01"
  );
  constant PROG_10 : ram_t := (
    x"1E", x"3C", x"76", x"1D", x"E0", x"F0", x"4E", x"1D",
    x"2F", x"4D", x"60", x"00", x"01", x"00", x"03", x"05"
  );
  constant PROG_11 : ram_t := (
    x"5A", x"E0", x"00", x"3F", x"86", x"61", x"E0", x"F0",
    x"00", x"00", x"00", x"00", x"00", x"00", x"00", x"01"
  );

  -- Nach Bitstream-Laden entspricht der Zustand dem Reset mit Programm 00.
  signal mar_reg : std_logic_vector(3 downto 0) := (others => '0');
  signal ram     : ram_t := PROG_00;

begin

  -- Kombinatorisches Lesen: RO = RAM[MAR vor der Flanke].
  ram_out <= ram(to_integer(unsigned(mar_reg)));

  -- MAR + RAM in einer Clock-Domain (clk), synchroner Reset active high.
  -- RI schreibt an die Adresse im MAR vor der Flanke (mar_reg, nicht addr_in).
  p_seq : process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        mar_reg <= (others => '0');
        case prog_sel is
          when "00" =>
            ram <= PROG_00;
          when "01" =>
            ram <= PROG_01;
          when "10" =>
            ram <= PROG_10;
          when "11" =>
            ram <= PROG_11;
          when others =>
            ram <= PROG_00;
        end case;
      elsif prog_valid = '1' then
        -- Vollstaendiger UART-Rahmen: RAM[0..15] := prog_data, MAR := 0.
        -- Konvention: RAM(i) = prog_data(8*i+7 downto 8*i);
        -- der Lader liefert RAM[n..15] bereits als 0.
        mar_reg <= (others => '0');
        for i in 0 to 15 loop
          ram(i) <= prog_data(8 * i + 7 downto 8 * i);
        end loop;
      else
        if mi_en = '1' then
          mar_reg <= addr_in;
        end if;
        if ri_en = '1' then
          ram(to_integer(unsigned(mar_reg))) <= data_in;
        end if;
      end if;
    end if;
  end process p_seq;

end architecture rtl;

sources.src/program_counter.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity program_counter is
  port (
    ce        : in  std_logic;
    clk       : in  std_logic;
    data_in   : in  std_logic_vector(3 downto 0);
    j_load    : in  std_logic;
    rst       : in  std_logic;
    count_out : out std_logic_vector(3 downto 0)
  );
end entity program_counter;

architecture rtl of program_counter is
  signal cnt : unsigned(3 downto 0) := (others => '0');
begin

  p_seq: process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        cnt <= (others => '0');
      elsif j_load = '1' then
        cnt <= unsigned(data_in);
      elsif ce = '1' then
        cnt <= cnt + 1;
      end if;
    end if;
  end process p_seq;

  count_out <= std_logic_vector(cnt);

end architecture rtl;

