end architecture rtl;

sources.src/uart_rx.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity uart_rx is
  generic (
    CLKS_PER_BIT : positive := 868
  );
  port (
    clk        : in  std_logic;
    rst        : in  std_logic;
    rx_in      : in  std_logic;
    data_out   : out std_logic_vector(7 downto 0);
    data_valid : out std_logic
  );
end entity uart_rx;

architecture rtl of uart_rx is

  type state_t is (S_IDLE, S_START, S_DATA, S_STOP, S_DONE);

  signal state    : state_t := S_IDLE;
  signal clk_cnt  : natural := 0;
  signal bit_idx  : natural range 0 to 7 := 0;
  signal shifter  : std_logic_vector(7 downto 0) := (others => '0');

begin

  -- UART-Empfaenger 8N1, LSB zuerst.
  -- Startbeginn an fallender Flanke (in IDLE: rx_in = '0').
  -- Abtastung jeweils in Bitmitte; Zeichen mit falschem
  -- Startbit (Mitte /= '0') oder Stoppbit (/= '1') wird verworfen.
  -- data_valid ist genau einen Takt lang '1', data_out haelt
  -- das letzte gueltige Zeichen. Synchroner Reset, active high.
  p_seq: process(clk)
    constant START_SAMPLE : natural := (CLKS_PER_BIT - 1) / 2;
  begin
    if rising_edge(clk) then
      if rst = '1' then
        state      <= S_IDLE;
        clk_cnt    <= 0;
        bit_idx    <= 0;
        shifter    <= (others => '0');
        data_out   <= (others => '0');
        data_valid <= '0';
      else
        data_valid <= '0';
        case state is
          when S_IDLE =>
            clk_cnt <= 0;
            bit_idx <= 0;
            if rx_in = '0' then
              state <= S_START;
            end if;

          when S_START =>
            if clk_cnt = START_SAMPLE then
              clk_cnt <= 0;
              if rx_in = '0' then
                state   <= S_DATA;
                bit_idx <= 0;
              else
                state <= S_IDLE;
              end if;
            else
              clk_cnt <= clk_cnt + 1;
            end if;

          when S_DATA =>
            if clk_cnt = CLKS_PER_BIT - 1 then
              clk_cnt <= 0;
              shifter(bit_idx) <= rx_in;
              if bit_idx = 7 then
                state <= S_STOP;
              else
                bit_idx <= bit_idx + 1;
              end if;
            else
              clk_cnt <= clk_cnt + 1;
            end if;

          when S_STOP =>
            if clk_cnt = CLKS_PER_BIT - 1 then
              clk_cnt <= 0;
              if rx_in = '1' then
                state <= S_DONE;
              else
                state <= S_IDLE;
              end if;
            else
              clk_cnt <= clk_cnt + 1;
            end if;

          when S_DONE =>
            data_out   <= shifter;
            data_valid <= '1';
            state      <= S_IDLE;

          when others =>
            state <= S_IDLE;
        end case;
      end if;
    end if;
  end process p_seq;

end architecture rtl;

sources.src/uart_tx.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity uart_tx is
  generic (
    CLKS_PER_BIT : positive := 868
  );
  port (
    clk     : in  std_logic;
    data_in : in  std_logic_vector(7 downto 0);
    rst     : in  std_logic;
    send_en : in  std_logic;
    busy    : out std_logic;
    tx_out  : out std_logic
  );
end entity uart_tx;

architecture rtl of uart_tx is
  type state_t is (IDLE, TX_START, TX_DATA, TX_STOP);
  signal state    : state_t := IDLE;
  signal cnt      : integer range 0 to 2147483647 := 0;
  signal bit_idx  : integer range 0 to 7 := 0;
  signal shift    : std_logic_vector(7 downto 0) := (others => '0');
  signal send_prev : std_logic := '0';
begin

  -- busy ist '1' waehrend des gesamten Rahmens (Start + 8 Daten + Stopp).
  -- Es wird ueber das registrierte state-Signal gebildet und ist daher
  -- erst den Takt nach send_en aktiv: Der OI-Mikroschritt, der das Senden
  -- ausloest, wird noch ausgefuehrt, danach sperrt clock_ctrl (oi+busy).
  busy <= '0' when state = IDLE else '1';

  -- Moore-Ausgaenge: tx_out haengt nur von registrierten Signalen ab,
  -- daher glitchfrei und exakt CLKS_PER_BIT Takte je Bit.
  p_out : process(all)
  begin
    case state is
      when IDLE =>
        tx_out <= '1';
      when TX_START =>
        tx_out <= '0';
      when TX_DATA =>
        tx_out <= shift(bit_idx);
      when TX_STOP =>
        tx_out <= '1';
    end case;
  end process p_out;

  p_seq : process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        state     <= IDLE;
        cnt       <= 0;
        bit_idx   <= 0;
        shift     <= (others => '0');
        send_prev <= '0';
      else
        case state is
          when IDLE =>
            if send_en = '1' and send_prev = '0' then
              -- Steigende Flanke von send_en: neues Zeichen latchen.
              -- Flankenauswertung verhindert Doppelstart, wenn send_en
              -- als Pegel (OI & Modus) ueber die Sperrzeit hinaus ansteht.
              shift   <= data_in;
              state   <= TX_START;
              cnt     <= 0;
            end if;
            send_prev <= send_en;

          when TX_START =>
            send_prev <= send_en;
            if cnt = CLKS_PER_BIT - 1 then
              state   <= TX_DATA;
              cnt     <= 0;
              bit_idx <= 0;
            else
              cnt <= cnt + 1;
            end if;

          when TX_DATA =>
            send_prev <= send_en;
            if cnt = CLKS_PER_BIT - 1 then
              if bit_idx = 7 then
                state <= TX_STOP;
                cnt   <= 0;
              else
                bit_idx <= bit_idx + 1;
                cnt     <= 0;
              end if;
            else
              cnt <= cnt + 1;
            end if;

          when TX_STOP =>
            send_prev <= send_en;
            if cnt = CLKS_PER_BIT - 1 then
              state <= IDLE;
              cnt   <= 0;
            else
              cnt <= cnt + 1;
            end if;
        end case;
      end if;
    end if;
  end process p_seq;

end architecture rtl;

sources.tests/alu_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
library std;
use std.env.all;

entity alu_tb is
end entity alu_tb;

architecture sim of alu_tb is
  constant CLK_PERIOD : time := 20 ns;

  signal clk        : std_logic := '0';
  signal rst        : std_logic := '1';
  signal a_in       : std_logic_vector(7 downto 0) := (others => '0');
  signal b_in       : std_logic_vector(7 downto 0) := (others => '0');
  signal sub        : std_logic := '0';
  signal fi_en      : std_logic := '0';
  signal result_out : std_logic_vector(7 downto 0);
  signal carry_out  : std_logic;
  signal zero_out   : std_logic;

  signal tb_done : boolean := false;
begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.alu
    port map (
      a_in       => a_in,
      b_in       => b_in,
      clk        => clk,
      carry_out  => carry_out,
      fi_en      => fi_en,
      rst        => rst,
      result_out => result_out,
      sub        => sub,
      zero_out   => zero_out
    );

  stim: process
    procedure wait_cyc(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
        wait for 1 ns;
      end loop;
    end procedure;

    -- apply one vector: set inputs, check combinational result,
    -- then clock FI and check registered flags
    procedure check_vec(
      constant va : in integer;
      constant vb : in integer;
      constant vsub : in std_logic;
      constant exp_res : in integer;
      constant exp_c : in std_logic;
      constant exp_z : in std_logic) is
    begin
      a_in <= std_logic_vector(to_unsigned(va, 8));
      b_in <= std_logic_vector(to_unsigned(vb, 8));
      sub <= vsub;
      fi_en <= '0';
      wait for 1 ns;
      report "CHECK t=" & time'image(now) & " vec a=" & integer'image(va)
        & " b=" & integer'image(vb) & " sub=" & std_logic'image(vsub)
        & " res=" & to_string(result_out) severity note;
      assert result_out = std_logic_vector(to_unsigned(exp_res, 8))
        report "REQ R18: ALU Ergebnis falsch a=" & integer'image(va)
        & " b=" & integer'image(vb) & " sub=" & std_logic'image(vsub) severity error;
      assert result_out = std_logic_vector(to_unsigned(exp_res, 8))
        report "REQ R16: EO-Busquelle muss ALU-Ergebnis liefern" severity error;
      -- uebernehme Flags mit FI
      fi_en <= '1';
      wait until rising_edge(clk);
      wait for 1 ns;
      fi_en <= '0';
      wait for 1 ns;
      report "CHECK t=" & time'image(now) & " flags c=" & std_logic'image(carry_out)
        & " z=" & std_logic'image(zero_out) & " res=" & to_string(result_out) severity note;
      assert carry_out = exp_c
        report "REQ R18: ALU Carry falsch" severity error;
      assert zero_out = exp_z
        report "REQ R18: ALU Zero falsch" severity error;
      assert carry_out = exp_c and zero_out = exp_z
        report "REQ R19: Flags-Register uebernimmt bei FI Carry/Zero" severity error;
    end procedure;
  begin
    -- Reset-Sequenz: mind. 2 Zyklen rst='1' (synchron, active high)
    rst <= '1';
    fi_en <= '0';
    a_in <= (others => '0');
    b_in <= (others => '0');
    sub <= '0';
    wait until rising_edge(clk);
    wait for 1 ns;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " im Reset c=" & std_logic'image(carry_out)
      & " z=" & std_logic'image(zero_out) severity note;
    assert carry_out = '0' and zero_out = '0'
      report "REQ R43: bei rst=1 Flags C/Z in 0/Ruhe" severity error;
    rst <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset res=" & to_string(result_out)
      & " c=" & std_logic'image(carry_out) & " z=" & std_logic'image(zero_out) severity note;
    assert carry_out = '0' and zero_out = '0'
      report "REQ R43: nach Reset Flags 0 (synchron active-high)" severity error;
    assert carry_out = '0' and zero_out = '0'
      report "REQ R51: Rahmen/Reset loescht C/Z (UART-Neustart)" severity error;
    assert result_out = X"00"
      report "REQ R18: nach Reset mit A=B=0 Ergebnis 0" severity error;

    -- ADD-Vektoren (PROMPT.md: Ergebnis=(A+B) mod 256, Carry=Uebertrag Bit7, Zero bei 0)
    check_vec(16#00#, 16#00#, '0', 16#00#, '0', '1');
    check_vec(16#01#, 16#02#, '0', 16#03#, '0', '0');
    check_vec(16#37#, 16#59#, '0', 16#90#, '0', '0'); -- 55+89=144 Fibonacci
    check_vec(16#59#, 16#90#, '0', 16#E9#, '0', '0'); -- 89+144=233
    check_vec(16#C8#, 16#64#, '0', 16#2C#, '1', '0'); -- 200+100=44 Uebertrag
    check_vec(16#FF#, 16#01#, '0', 16#00#, '1', '1'); -- 255+1=0
    check_vec(16#FF#, 16#00#, '0', 16#FF#, '0', '0');
    check_vec(16#80#, 16#80#, '0', 16#00#, '1', '1'); -- 128+128=0

    -- R19: ohne FI keine Uebernahme (Flags halten)
    a_in <= X"01";
    b_in <= X"01";
    sub <= '0';
    fi_en <= '0';
    wait for 1 ns;
    -- Flags sind noch vom letzten Vektor (128+128 => C=1,Z=1)
    report "CHECK t=" & time'image(now) & " halte c=" & std_logic'image(carry_out)
      & " z=" & std_logic'image(zero_out) & " res=" & to_string(result_out) severity note;
    assert result_out = X"02"
      report "REQ R18: ADD 1+1=2 kombinatorisch" severity error;
    assert result_out = X"02"
      report "REQ R16: EO folgt kombinatorisch ohne Takt" severity error;
    wait_cyc(2);
    assert carry_out = '1' and zero_out = '1'
      report "REQ R19: ohne FI keine Flag-Aenderung (halten)" severity error;

    -- SUB-Vektoren (PROMPT.md: A+(not B)+1, Carry=1 genau bei A>=B, Zero bei 0)
    check_vec(16#05#, 16#03#, '1', 16#02#, '1', '0'); -- 5-3=2
    check_vec(16#03#, 16#05#, '1', 16#FE#, '0', '0'); -- 3-5=0xFE borrow (HW-Test borrow_3_minus_5)
    check_vec(16#0A#, 16#0A#, '1', 16#00#, '1', '1'); -- 10-10=0
    check_vec(16#00#, 16#01#, '1', 16#FF#, '0', '0'); -- 0-1
    check_vec(16#00#, 16#00#, '1', 16#00#, '1', '1'); -- 0-0
    check_vec(16#0A#, 16#01#, '1', 16#09#, '1', '0'); -- 10-1=9 Countdown-Schritt
    check_vec(16#01#, 16#02#, '1', 16#FF#, '0', '0');
    check_vec(16#FF#, 16#FF#, '1', 16#00#, '1', '1');

    -- R19: FI=0 haelt auch nach SUB-Vektor
    a_in <= X"FF";
    b_in <= X"00";
    sub <= '1';
    fi_en <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " sub FF-00 res=" & to_string(result_out)
      & " c=" & std_logic'image(carry_out) & " z=" & std_logic'image(zero_out) severity note;
    assert result_out = X"FF"
      report "REQ R18: SUB FF-00=FF" severity error;
    wait_cyc(2);
    -- Flags noch vom letzten check_vec (FF-FF => C=1,Z=1)
    assert carry_out = '1' and zero_out = '1'
      report "REQ R19: Flags halten ohne FI nach SUB" severity error;

    -- R43: synchroner Reset wirkt erst mit Flanke, loescht dann C/Z
    -- erst Flags auf 1 bringen (FF+01 => C=1,Z=1 via FI)
    a_in <= X"FF";
    b_in <= X"01";
    sub <= '0';
    fi_en <= '1';
    wait until rising_edge(clk);
    wait for 1 ns;
    fi_en <= '0';
    wait for 1 ns;
    assert carry_out = '1' and zero_out = '1'
      report "REQ R19: Vorbereitung Flags=1 vor Reset-Test" severity error;
    rst <= '1';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " rst=1 vor Flanke c=" & std_logic'image(carry_out)
      & " z=" & std_logic'image(zero_out) severity note;
    assert carry_out = '1' and zero_out = '1'
      report "REQ R43: synchroner Reset wirkt erst mit Flanke" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset-Flanke c=" & std_logic'image(carry_out)
      & " z=" & std_logic'image(zero_out) severity note;
    assert carry_out = '0' and zero_out = '0'
      report "REQ R43: Reset-Flanke loescht C/Z" severity error;
    assert carry_out = '0' and zero_out = '0'
      report "REQ R51: Loader-Neustart loescht C/Z wie Reset" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    rst <= '0';
    wait for 1 ns;
    assert carry_out = '0' and zero_out = '0'
      report "REQ R43: nach rst=0 bleiben Flags 0" severity error;

    -- R16: Bus-Idle-Fall: result liegt weiter an, ist aber nur bei EO relevant;
    -- pruefe, dass result_out jederzeit dem ALU-Wert folgt (Mux-Quelle EO)
    a_in <= X"0F";
    b_in <= X"01";
    sub <= '0';
    wait for 1 ns;
    assert result_out = X"10"
      report "REQ R16: EO-Quelle 0F+01=10" severity error;
    a_in <= X"0F";
    b_in <= X"01";
    sub <= '1';
    wait for 1 ns;
    assert result_out = X"0E"
      report "REQ R16: EO-Quelle 0F-01=0E mit SU" severity error;
    assert result_out = X"0E"
      report "REQ R18: SUB 0F-01=0E, Carry=1 kein Borgen" severity error;
    fi_en <= '1';
    wait until rising_edge(clk);
    wait for 1 ns;
    fi_en <= '0';
    wait for 1 ns;
    assert carry_out = '1' and zero_out = '0'
      report "REQ R18: SUB 0F-01 Carry=1 (A>=B)" severity error;

    report "CHECK t=" & time'image(now) & " alle ALU-Pruefungen fertig" severity note;
    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop(0);
    wait;
  end process stim;

end architecture sim;

sources.tests/ben_eater_cpu_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity ben_eater_cpu_tb is
end entity ben_eater_cpu_tb;

architecture sim of ben_eater_cpu_tb is
  constant CLK_PERIOD : time := 10 ns;   -- 100 MHz Boardtakt
  constant BIT_TIME   : time := 80 ns;   -- CLKS_PER_BIT=8 * 10 ns
  constant RX_TIMEOUT : time := 30 us;

  signal clk      : std_logic := '0';
  signal rst      : std_logic := '1';
  signal btn_step : std_logic := '0';
  signal sw       : std_logic_vector(3 downto 0) := "0000";
  signal led      : std_logic_vector(3 downto 0);
  signal uart_rx  : std_logic := '1';
  signal uart_tx  : std_logic;

  signal tb_done : boolean := false;

  type byte_array_t is array (natural range <>) of std_logic_vector(7 downto 0);

  -- Hardwaretest-Vektoren aus PROMPT.md (Programme und erwartete Antworten)
  constant PROG_FIB_HALT : byte_array_t(0 to 15) := (
    x"E0", x"2E", x"7B", x"4F", x"1E", x"4D", x"1F", x"4E",
    x"1D", x"60", x"00", x"F0", x"00", x"00", x"01", x"00");
  constant EXP_FIB : byte_array_t(0 to 12) := (
    x"00", x"01", x"01", x"02", x"03", x"05", x"08",
    x"0D", x"15", x"22", x"37", x"59", x"90");
  constant PROG_MUL79 : byte_array_t(0 to 15) := (
    x"1E", x"3C", x"76", x"1D", x"E0", x"F0", x"4E", x"1D",
    x"2F", x"4D", x"60", x"00", x"01", x"00", x"07", x"09");
  constant EXP_MUL : byte_array_t(0 to 0) := (0 => x"3F");
  constant PROG_CD5 : byte_array_t(0 to 15) := (
    x"55", x"E0", x"3F", x"85", x"61", x"E0", x"F0", x"00",
    x"00", x"00", x"00", x"00", x"00", x"00", x"00", x"01");
  constant EXP_CD5 : byte_array_t(0 to 5) := (
    x"05", x"04", x"03", x"02", x"01", x"00");
  constant PROG_BOR : byte_array_t(0 to 15) := (
    x"53", x"3F", x"75", x"E0", x"F0", x"51", x"E0", x"F0",
    x"00", x"00", x"00", x"00", x"00", x"00", x"00", x"05");
  constant EXP_BOR : byte_array_t(0 to 0) := (0 => x"FE");
  -- Endlosschleife OUT / JMP 0 (gibt dauerhaft OUT aus, endet nie mit HLT)
  constant PROG_LOOP : byte_array_t(0 to 1) := (x"E0", x"60");
  -- LDI 5, dann Opcode 1001 (muss wie NOP wirken), OUT, HLT
  constant PROG_NOP9 : byte_array_t(0 to 3) := (x"55", x"90", x"E0", x"F0");
  constant TRAIL : byte_array_t(0 to 5) := (
    x"53", x"54", x"41", x"52", x"54", x"0A");  -- "START" + LF

  function hex4(nib : std_logic_vector(3 downto 0)) return string is
    variable c : character;
  begin
    case nib is
      when "0000" => c := '0';
      when "0001" => c := '1';
      when "0010" => c := '2';
      when "0011" => c := '3';
      when "0100" => c := '4';
      when "0101" => c := '5';
      when "0110" => c := '6';
      when "0111" => c := '7';
      when "1000" => c := '8';
      when "1001" => c := '9';
      when "1010" => c := 'A';
      when "1011" => c := 'B';
      when "1100" => c := 'C';
      when "1101" => c := 'D';
      when "1110" => c := 'E';
      when "1111" => c := 'F';
      when others => c := 'X';
    end case;
    return (1 => c);
  end function hex4;

  function hex8(b : std_logic_vector(7 downto 0)) return string is
  begin
    return hex4(b(7 downto 4)) & hex4(b(3 downto 0));
  end function hex8;

begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.ben_eater_cpu
    generic map (
      TICK_CYCLES     => 2,
      DEBOUNCE_CYCLES => 2,
      CLKS_PER_BIT    => 8
    )
    port map (
      clk      => clk,
      rst      => rst,
      btn_step => btn_step,
      sw       => sw,
      led      => led,
      uart_rx  => uart_rx,
      uart_tx  => uart_tx
    );

  stim: process
    variable b        : std_logic_vector(7 downto 0);
    variable n        : integer;
    variable t0, t1   : time;

    procedure wait_cycles(k : positive) is
    begin
      for i in 1 to k loop
        wait until rising_edge(clk);
      end loop;
    end procedure wait_cycles;

    procedure do_reset is
    begin
      rst <= '1';
      wait_cycles(10);
      rst <= '0';
      wait_cycles(3);
    end procedure do_reset;

    procedure press_once is
    begin
      btn_step <= '1';
      wait_cycles(12);
      btn_step <= '0';
      wait_cycles(12);
    end procedure press_once;

    procedure uart_send_byte(v : std_logic_vector(7 downto 0)) is
    begin
      uart_rx <= '0';                       -- Startbit
      wait for BIT_TIME;
      for i in 0 to 7 loop                  -- 8 Datenbits, LSB zuerst
        uart_rx <= v(i);
        wait for BIT_TIME;
      end loop;
      uart_rx <= '1';                       -- Stoppbit
      wait for BIT_TIME;
      wait for CLK_PERIOD * 4;              -- Luecke zwischen Zeichen
    end procedure uart_send_byte;

    -- Ein Zeichen mit defektem Stoppbit (Stopp = '0'): muss verworfen werden.
    procedure uart_send_byte_bad_stop(v : std_logic_vector(7 downto 0)) is
    begin
      uart_rx <= '0';
      wait for BIT_TIME;
      for i in 0 to 7 loop
        uart_rx <= v(i);
        wait for BIT_TIME;
      end loop;
      uart_rx <= '0';                       -- defektes Stoppbit
      wait for BIT_TIME;
      uart_rx <= '1';
      wait for CLK_PERIOD * 4;
    end procedure uart_send_byte_bad_stop;

    procedure uart_send_frame(prog : byte_array_t) is
      variable len : std_logic_vector(7 downto 0);
    begin
      len := std_logic_vector(to_unsigned(prog'length, 8));
      uart_send_byte(len);
      uart_send_byte(x"00");
      uart_send_byte(x"00");
      uart_send_byte(x"00");
      for i in prog'range loop
        uart_send_byte(prog(i));
      end loop;
      for i in TRAIL'range loop
        uart_send_byte(TRAIL(i));
      end loop;
      -- Keine Warteluecke: das erste Antwortzeichen beginnt wenige Takte
      -- nach dem Rahmen; der Aufrufer wartet sofort auf das Startbit.
    end procedure uart_send_frame;

    procedure uart_recv_byte(v : out std_logic_vector(7 downto 0)) is
      variable r : std_logic_vector(7 downto 0);
    begin
      wait until falling_edge(uart_tx) for RX_TIMEOUT;
      assert uart_tx = '0'
        report "REQ R75: UART-Antwortbyte fehlt (Timeout beim Startbit)"
        severity error;
      wait for BIT_TIME * 3 / 2;            -- Mitte von Datenbit 0
      for i in 0 to 7 loop
        r(i) := uart_tx;
        wait for BIT_TIME;
      end loop;
      -- Abtastpunkt liegt jetzt in der Stoppbit-Mitte
      assert uart_tx = '1'
        report "REQ R49: UART-Stoppbit ist nicht '1'"
        severity error;
      v := r;
    end procedure uart_recv_byte;

    procedure wait_led(exp : std_logic_vector(3 downto 0); tmax : time) is
    begin
      wait until led = exp for tmax;
    end procedure wait_led;

  begin
    -- ================================================================
    -- 1) Fibonacci-Festprogramm "00" im automatischen Takt (sw = 0000)
    -- ================================================================
    wait_cycles(10);  -- rst='1' liegt von Beginn an (Power-on)
    assert led = "0000" report "REQ R4: synchroner Reset active high loescht led" severity error;
    assert led = "0000" report "REQ R43: bei rst=1 sind alle Register/LED in 0/Ruhe" severity error;
    assert uart_tx = '1' report "REQ R43: bei rst=1 ist der UART-Sender in Ruhe (tx=1)" severity error;
    rst <= '0';
    wait_cycles(3);

    wait_led("0001", 30 us);
    assert led = "0001" report "REQ R44: Power-on-/Reset-Zustand startet Fibonacci (Programm 00)" severity error;
    assert led = "0001" report "REQ R45: Fibonacci-Festprogramm 00 laeuft (erstes OUT=1)" severity error;
    assert led = "0001" report "REQ R16: Bus-Multiplexer liefert Operanden/Ergebnisse korrekt" severity error;
    assert led = "0001" report "REQ R21: Steuerwerk erzeugt wirksame Steuersignale (Fetch+LDI+OUT)" severity error;
    assert led = "0001" report "REQ R22: Fetch in T0 (MI+CO) und T1 (RO+II+CE)" severity error;
    assert led = "0001" report "REQ R28: LDI n in T2 (IO+AI)" severity error;
    assert led = "0001" report "REQ R33: OUT-Befehl in T2 (AO+OI)" severity error;
    report "CHECK t=" & time'image(now) & " fib led=" & hex4(led) severity note;
    wait_led("0010", 30 us);
    assert led = "0010" report "REQ R25: ADD a (T2 IO+MI, T3 RO+BI, T4 EO+AI+FI), 1+1=2" severity error;
    assert led = "0010" report "REQ R19: Flags-Register uebernimmt bei FI Carry/Zero der ALU" severity error;
    wait_led("0011", 30 us);
    assert led = "0011" report "REQ R27: STA a (T2 IO+MI, T3 AO+RI) speichert Zwischensummen" severity error;
    assert led = "0011" report "REQ R35: Mikroschritte wirken gleichzeitig mit Vor-Flanken-Werten (RI nutzt MAR vor Flanke)" severity error;
    wait_led("0101", 30 us);
    assert led = "0101" report "REQ R24: LDA a (T2 IO+MI, T3 RO+AI), OUT=5" severity error;
    wait_led("1000", 30 us);
    assert led = "1000" report "REQ R18: ALU addiert (A+B) mod 256, 5+3=8, Carry/Zero korrekt" severity error;
    assert led = "1000" report "REQ R36: Mikroschrittzaehler rueckt nach jedem Schritt vor (T4->T0)" severity error;
    assert led = "1000" report "REQ R29: JMP t in T2 (IO+J)" severity error;
    report "CHECK t=" & time'image(now) & " fib led=" & hex4(led) severity note;

    -- oberes Halbbyte: OUT=8 -> oben 0
    sw <= "0001";
    wait_cycles(10);
    assert led = "0000" report "REQ R7: sw(0)=1 zeigt oberes OUT-Halbbyte" severity error;
    assert led = "0000" report "REQ R42: led-Register uebernimmt jeden Takt das gewaehlte Halbbyte" severity error;
    report "CHECK t=" & time'image(now) & " fib-upper led=" & hex4(led) severity note;

    -- ================================================================
    -- 2) Zaehl-Festprogramm "01" (sw = 0100), Anfang 1,2,3
    -- ================================================================
    sw <= "0100";
    wait_cycles(6);
    do_reset;
    assert led = "0000" report "REQ R9: sw(3 downto 2) waehlt das Reset-Programm (Zaehlen gestartet, OUT=0)" severity error;
    wait_led("0001", 30 us);
    assert led = "0001" report "REQ R46: Zaehl-Festprogramm 01 zaehlt aufwaerts (OUT=1)" severity error;
    wait_led("0010", 30 us);
    assert led = "0010" report "REQ R46: Zaehl-Festprogramm 01 (OUT=2)" severity error;
    assert led = "0010" report "REQ R30: JC t springt nur bei C=1 (kein Carry beim Hochzaehlen)" severity error;
    wait_led("0011", 30 us);
    assert led = "0011" report "REQ R46: Zaehl-Festprogramm 01 (OUT=3)" severity error;
    report "CHECK t=" & time'image(now) & " count led=" & hex4(led) severity note;

    -- ================================================================
    -- 3) Multiplikation "10" (sw = 1000): OUT=15, danach Halt
    -- ================================================================
    sw <= "1000";
    wait_cycles(6);
    do_reset;
    n := 0;
    for i in 1 to 5000 loop
      exit when led = "1111";
      wait until rising_edge(clk);
      n := n + 1;
    end loop;
    assert led = "1111" report "REQ R47: Multiplikation 3x5 zeigt OUT=15" severity error;
    assert led = "1111" report "REQ R9: sw(3 downto 2)=10 waehlt Programm 10" severity error;
    assert led = "1111" report "REQ R8: sw(1)=0 waehlt automatischen Takt (ein Mikroschritt je Tick)" severity error;
    assert led = "1111" report "REQ R26: SUB a mit SU+FI, Borrow-Pfad (Schleifenabbruch bei C=0)" severity error;
    assert led = "1111" report "REQ R30: JC t genommen bei C=1 und uebergangen bei C=0" severity error;
    assert led = "1111" report "REQ R41: Schrittfreigabe ist Tick im Board-Modus (Auto-Takt laeuft)" severity error;
    assert n < 2000 report "REQ R40: Tick-Generator pulst schnell (TICK_CYCLES=2)" severity error;
    assert n < 2000 report "REQ R72: Testbench-Generics TICK_CYCLES=2, DEBOUNCE_CYCLES=2, CLKS_PER_BIT=8 (schneller Fortschritt)" severity error;
    assert led = "1111" report "REQ R73: Programm 10 im Auto-Takt: OUT=15" severity error;
    report "CHECK t=" & time'image(now) & " mul15 led=" & hex4(led) & " cycles=" & integer'image(n) severity note;
    -- oberes Halbbyte von 15 ist 0
    sw <= "1001";
    wait_cycles(10);
    assert led = "0000" report "REQ R7: sw(0)=1 zeigt oberes Halbbyte von OUT=15 (0)" severity error;
    sw <= "1000";
    wait_cycles(5);
    -- HLT: keine Aenderung mehr
    wait_cycles(200);
    assert led = "1111" report "REQ R34: HLT in T2 haelt die CPU an (OUT bleibt 15)" severity error;
    assert led = "1111" report "REQ R37: bei HLT frieren alle Register und der T-Zaehler ein" severity error;
    -- Board-Modus sendet nichts
    wait until uart_tx = '0' for 5 us;
    assert uart_tx = '1' report "REQ R52: im Board-Modus bleibt uart_tx=1 (kein Senden)" severity error;
    assert uart_tx = '1' report "REQ R77: im Board-Modus wird nichts gesendet" severity error;
    report "CHECK t=" & time'image(now) & " mul-halt led=" & hex4(led) severity note;

    -- ================================================================
    -- 4) Countdown "11" (sw = 1100): Folge 10..0, danach Halt
    -- ================================================================
    sw <= "1100";
    wait_cycles(6);
    do_reset;
    wait_led("1010", 30 us);
    assert led = "1010" report "REQ R48: Countdown-Programm 11 startet mit OUT=10" severity error;
    assert led = "1010" report "REQ R28: LDI 10 laedt A" severity error;
    assert led = "1010" report "REQ R73: Programm 11 im Auto-Takt: OUT=10" severity error;
    report "CHECK t=" & time'image(now) & " cd led=" & hex4(led) severity note;
    -- oberes Halbbyte von 10 ist 0
    sw <= "1101";
    wait_cycles(10);
    assert led = "0000" report "REQ R7: oberes Halbbyte von OUT=10 ist 0" severity error;
    assert led = "0000" report "REQ R42: led folgt dem OUT-Wert ueber sw(0)-Mux" severity error;
    sw <= "1100";
    wait_cycles(5);
    wait_led("1001", 30 us);
    assert led = "1001" report "REQ R48: Countdown OUT=9" severity error;
    wait_led("1000", 30 us);
    assert led = "1000" report "REQ R48: Countdown OUT=8" severity error;
    wait_led("0111", 30 us);
    assert led = "0111" report "REQ R23: NOP 0000 hat keine weiteren Signale (Zaehler laeuft weiter)" severity error;
    wait_led("0110", 30 us);
    assert led = "0110" report "REQ R48: Countdown OUT=6" severity error;
    wait_led("0101", 30 us);
    assert led = "0101" report "REQ R48: Countdown OUT=5" severity error;
    wait_led("0100", 30 us);
    assert led = "0100" report "REQ R48: Countdown OUT=4" severity error;
    wait_led("0011", 30 us);
    assert led = "0011" report "REQ R48: Countdown OUT=3" severity error;
    wait_led("0010", 30 us);
    assert led = "0010" report "REQ R48: Countdown OUT=2" severity error;
    wait_led("0001", 30 us);
    assert led = "0001" report "REQ R48: Countdown OUT=1" severity error;
    assert led = "0001" report "REQ R26: SUB erniedrigt A (1-1=0 im letzten Schritt)" severity error;
    wait_led("0000", 30 us);
    assert led = "0000" report "REQ R48: Countdown OUT=0, danach Halt" severity error;
    assert led = "0000" report "REQ R31: JZ t springt nur bei Z=1 (Schleifenende bei A=0)" severity error;
    report "CHECK t=" & time'image(now) & " cd-end led=" & hex4(led) severity note;
    wait_cycles(200);
    assert led = "0000" report "REQ R34: HLT nach Countdown (OUT bleibt 0)" severity error;
    assert led = "0000" report "REQ R37: Haltezustand friert CPU bis Reset/UART-Programm ein" severity error;

    -- ================================================================
    -- 5) Einzeltakt (sw = 1110): kein Druck -> kein Fortschritt,
    --    8 Druecke -> OUT=10 (exakt ein Mikroschritt je Druck)
    -- ================================================================
    sw <= "1110";
    wait_cycles(6);
    do_reset;
    wait_cycles(20);
    assert led = "0000" report "REQ R5: im Einzeltakt ohne Tastendruck kein Mikroschritt" severity error;
    assert led = "0000" report "REQ R8: sw(1)=1 waehlt Einzeltakt ueber btn_step" severity error;
    -- 1-Takt-Stoerimpuls darf keinen Schritt ausloesen (Sync + Entpreller)
    wait until falling_edge(clk);
    btn_step <= '1';
    wait until falling_edge(clk);
    btn_step <= '0';
    wait_cycles(20);
    assert led = "0000" report "REQ R38: Eingangs-Synchronisierer (2 FF) filtern kurze Impulse" severity error;
    assert led = "0000" report "REQ R39: Entpreller braucht DEBOUNCE_CYCLES stabile Takte (1-Takt-Puls -> kein rise)" severity error;
    -- 7 Druecke: Fetch + LDI ohne OUT -> OUT bleibt 0
    for i in 1 to 7 loop
      press_once;
    end loop;
    assert led = "0000" report "REQ R5: jeder Druck genau ein Mikroschritt (nach 7 Schritten noch kein OUT)" severity error;
    assert led = "0000" report "REQ R20: T-Zaehler T0..T4 aus Opcode+Flags (nach 7 Schritten: T3 ohne OUT-Signal)" severity error;
    assert led = "0000" report "REQ R36: T-Zaehler rueckt pro Druck genau eins weiter" severity error;
    press_once;  -- 8. Druck: T2 von OUT -> OUT=10
    assert led = "1010" report "REQ R74: im Einzeltakt steht 10 nach genau 8 Druecken in OUT" severity error;
    assert led = "1010" report "REQ R5: 8. Druck fuehrt 8. Mikroschritt aus (OUT=10)" severity error;
    assert led = "1010" report "REQ R22: Fetch T0/T1 + OUT-T2 in exakt 8 Mikroschritten" severity error;
    assert led = "1010" report "REQ R33: OUT-Befehl (AO+OI) im 8. Mikroschritt" severity error;
    assert led = "1010" report "REQ R39: Entpreller liefert genau einen rise je Tastendruck" severity error;
    report "CHECK t=" & time'image(now) & " single-step led=" & hex4(led) severity note;

    -- ================================================================
    -- 6) UART: fibonacci_halt (13 Antwortbytes)
    -- ================================================================
    sw <= "0000";
    wait_cycles(6);
    do_reset;
    uart_send_frame(PROG_FIB_HALT);
    t0 := now;
    for i in EXP_FIB'range loop
      if i = 0 then
        wait until falling_edge(uart_tx) for RX_TIMEOUT;
        assert uart_tx = '0' report "REQ R51: nach vollem Rahmen startet der UART-Modus (erstes OUT kommt)" severity error;
        assert (now - t0) < 5 us report "REQ R41: im UART-Modus ein Mikroschritt je Takt (schnelles erstes Zeichen)" severity error;
        t0 := now;  -- fallende Flanke des Startbits
        wait for BIT_TIME * 3 / 2;
        for k in 0 to 7 loop
          b(k) := uart_tx;
          wait for BIT_TIME;
        end loop;
        assert uart_tx = '1' report "REQ R49: UART 8N1 mit Stoppbit 1 (erstes Zeichen)" severity error;
        t1 := now;  -- Stoppbit-Mitte: 1,5 + 7 + 1 = 9,5 Bitzeiten = 760 ns
        assert (t1 - t0) >= 750 ns and (t1 - t0) <= 770 ns
          report "REQ R72: CLKS_PER_BIT=8 (9,5 Bit * 80 ns = 760 ns)" severity error;
      else
        uart_recv_byte(b);
      end if;
      assert b = EXP_FIB(i)
        report "REQ R55: fibonacci_halt Byte " & integer'image(i) &
               " erwartet " & hex8(EXP_FIB(i)) & " erhalten " & hex8(b)
        severity error;
    end loop;
    assert b = EXP_FIB(EXP_FIB'right)
      report "REQ R75: UART-Laden mit Hardwaretests, Antwortbytes auf uart_tx (fibonacci vollstaendig)"
      severity error;
    report "CHECK t=" & time'image(now) & " fib-uart last=" & hex8(b) severity note;

    -- ================================================================
    -- 7) UART: multiply_7x9 -> 3f
    -- ================================================================
    uart_send_frame(PROG_MUL79);
    uart_recv_byte(b);
    assert b = x"3F" report "REQ R56: multiply_7x9 antwortet 3f (7*9=63), erhalten " & hex8(b) severity error;
    report "CHECK t=" & time'image(now) & " mul79=" & hex8(b) severity note;

    -- ================================================================
    -- 8) UART: countdown_5 -> 05 04 03 02 01 00
    -- ================================================================
    uart_send_frame(PROG_CD5);
    for i in EXP_CD5'range loop
      uart_recv_byte(b);
      assert b = EXP_CD5(i)
        report "REQ R57: countdown_5 Byte " & integer'image(i) &
               " erwartet " & hex8(EXP_CD5(i)) & " erhalten " & hex8(b)
        severity error;
    end loop;
    report "CHECK t=" & time'image(now) & " cd5 last=" & hex8(b) severity note;

    -- ================================================================
    -- 9) UART: borrow_3_minus_5 -> fe
    -- ================================================================
    uart_send_frame(PROG_BOR);
    uart_recv_byte(b);
    assert b = x"FE" report "REQ R58: borrow_3_minus_5 antwortet fe (3-5 mod 256), erhalten " & hex8(b) severity error;
    assert b = x"FE" report "REQ R18: SUB mit SU: (A+(not B)+1) mod 256, Carry=0 bei A<B" severity error;
    assert b = x"FE" report "REQ R19: FI uebernimmt C=0/Z=0, JC wird nicht genommen" severity error;
    report "CHECK t=" & time'image(now) & " borrow=" & hex8(b) severity note;

    -- ================================================================
    -- 10) Zeichen mit defektem Stoppbit wird verworfen;
    --     danach laeuft ein gueltiger Rahmen trotzdem
    -- ================================================================
    uart_send_byte_bad_stop(x"55");
    report "CHECK t=" & time'image(now) & " bad-stop gesendet" severity note;
    uart_send_frame(PROG_MUL79);
    uart_recv_byte(b);
    assert b = x"3F" report "REQ R49: Zeichen mit falschem Stoppbit verworfen (Folgerahmen ok), erhalten " & hex8(b) severity error;

    -- ================================================================
    -- 11) Rahmen mit Laenge 17 wird verworfen, danach gueltiger Rahmen
    -- ================================================================
    uart_send_byte(x"11");  -- Laenge 17: ausserhalb 1..16
    uart_send_byte(x"00");
    uart_send_byte(x"00");
    uart_send_byte(x"00");
    wait for CLK_PERIOD * 20;
    wait until uart_tx = '0' for 2 us;
    assert uart_tx = '1' report "REQ R50: Rahmen mit n=17 verworfen (kein Neustart, kein Zeichen)" severity error;
    assert uart_tx = '1' report "REQ R76: Laenge-17-Rahmen verworfen (keine Antwort)" severity error;
    report "CHECK t=" & time'image(now) & " len17 discarded" severity note;
    uart_send_frame(PROG_CD5);
    uart_recv_byte(b);
    assert b = x"05" report "REQ R76: nach verworfenem Rahmen laeuft gueltiger Rahmen (countdown erstes Byte 05), erhalten " & hex8(b) severity error;
    for i in 1 to EXP_CD5'right loop
      uart_recv_byte(b);
      assert b = EXP_CD5(i)
        report "REQ R50: Laderahmen LE-Laenge + n Bytes + START-LF (Folgebyte " & integer'image(i) & ")"
        severity error;
    end loop;
    report "CHECK t=" & time'image(now) & " after-invalid last=" & hex8(b) severity note;

    -- ================================================================
    -- 12) Erstes Rahmenbyte im UART-Modus haelt CPU an (Endlos-OUT)
    -- ================================================================
    uart_send_frame(PROG_LOOP);
    uart_recv_byte(b);
    assert b = x"00" report "REQ R53: Endlos-OUT-Programm sendet im UART-Modus (00), erhalten " & hex8(b) severity error;
    -- nur erstes Laengenbyte des neuen Rahmens senden -> CPU muss anhalten
    uart_send_byte(x"10");  -- n=16, Rest folgt spaeter
    report "CHECK t=" & time'image(now) & " first len byte sent, CPU muss halten" severity note;
    wait until falling_edge(uart_tx) for 2 us;
    assert uart_tx = '1' report "REQ R53: erstes Rahmenbyte haelt CPU bis Rahmenende an (kein Zeichen)" severity error;
    -- Rahmen vervollstaendigen (Rest von multiply_7x9)
    uart_send_byte(x"00");
    uart_send_byte(x"00");
    uart_send_byte(x"00");
    for i in PROG_MUL79'range loop
      uart_send_byte(PROG_MUL79(i));
    end loop;
    for i in TRAIL'range loop
      uart_send_byte(TRAIL(i));
    end loop;
    uart_recv_byte(b);
    assert b = x"3F" report "REQ R53: nach vollstaendigem Rahmen laeuft neues Programm (3f), erhalten " & hex8(b) severity error;
    report "CHECK t=" & time'image(now) & " resume=" & hex8(b) severity note;

    -- ================================================================
    -- 13) Opcode 1001 verhaelt sich wie NOP (LDI 5, 0x90, OUT, HLT)
    -- ================================================================
    uart_send_frame(PROG_NOP9);
    uart_recv_byte(b);
    assert b = x"05" report "REQ R32: Opcodes 1001-1101 wie NOP (Antwort 05), erhalten " & hex8(b) severity error;
    report "CHECK t=" & time'image(now) & " nop9=" & hex8(b) severity note;

    -- ================================================================
    -- 14) Reset fuehrt in den Board-Modus zurueck (Fibonacci, tx=1)
    -- ================================================================
    sw <= "0000";
    wait_cycles(6);
    rst <= '1';
    wait_cycles(10);
    assert uart_tx = '1' report "REQ R43: Reset setzt UART-Sender zurueck (tx=1)" severity error;
    assert led = "0000" report "REQ R4: Reset wirkt synchron active high" severity error;
    rst <= '0';
    wait_cycles(3);
    wait until uart_tx = '0' for 5 us;
    assert uart_tx = '1' report "REQ R77: Reset fuehrt in den Board-Modus zurueck (Stille auf tx)" severity error;
    wait_led("0001", 30 us);
    assert led = "0001" report "REQ R77: nach Reset laeuft wieder das Fibonacci-Festprogramm" severity error;
    report "CHECK t=" & time'image(now) & " back-to-board led=" & hex4(led) severity note;

    -- ================================================================
    -- Ende
    -- ================================================================
    report "TB_COMPLETE" severity note;
    tb_done <= true;
    std.env.stop(0);
    wait;
  end process stim;

end architecture sim;

sources.tests/clock_ctrl_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity clock_ctrl_tb is
end entity clock_ctrl_tb;

architecture sim of clock_ctrl_tb is
  constant CLK_PERIOD     : time := 10 ns;
  constant TICK_CYCLES_TB : positive := 4;

  signal clk         : std_logic := '0';
  signal halted      : std_logic := '0';
  signal loader_busy : std_logic := '0';
  signal oi_active   : std_logic := '0';
  signal rst         : std_logic := '1';
  signal step_rise   : std_logic := '0';
  signal sw_step     : std_logic := '0';
  signal tx_busy     : std_logic := '0';
  signal uart_mode   : std_logic := '0';
  signal step_enable : std_logic;
  signal tick        : std_logic;

  signal tb_done : boolean := false;
begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.clock_ctrl
    generic map (
      TICK_CYCLES => TICK_CYCLES_TB
    )
    port map (
      clk         => clk,
      halted      => halted,
      loader_busy => loader_busy,
      oi_active   => oi_active,
      rst         => rst,
      step_rise   => step_rise,
      sw_step     => sw_step,
      tx_busy     => tx_busy,
      uart_mode   => uart_mode,
      step_enable => step_enable,
      tick        => tick
    );

  stim: process
    procedure wait_cycles(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
      end loop;
    end procedure;
  begin
    -- Reset sequence (min. 2 Zyklen rst='1')
    halted      <= '0';
    loader_busy <= '0';
    oi_active   <= '0';
    rst         <= '1';
    step_rise   <= '0';
    sw_step     <= '0';
    tx_busy     <= '0';
    uart_mode   <= '0';
    wait_cycles(3);
    wait for 1 ns;
    report "CHECK reset held t=" & time'image(now) & " tick=" & std_logic'image(tick)
      & " step_enable=" & std_logic'image(step_enable) severity note;
    assert tick = '0'
      report "REQ R4: tick muss im synchronen Reset 0 sein (Zaehler gehalten)" severity error;
    assert tick = '0'
      report "REQ R43: Tick-Zaehler muss bei rst=1 in 0/Ruhe stehen" severity error;
    assert step_enable = '0'
      report "REQ R41: Board-Auto step_enable=tick muss im Reset 0 sein" severity error;

    -- Reset loesen
    rst <= '0';

    -- R40: Tick-Periode 4 (tick genau 1 Takt je 4 Takte)
    for k in 1 to 8 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      report "CHECK R40 k=" & integer'image(k) & " t=" & time'image(now)
        & " tick=" & std_logic'image(tick) severity note;
      if (k mod 4) = 3 then
        assert tick = '1'
          report "REQ R40: Tick muss bei TICK_CYCLES=4 an Kante " & integer'image(k) & " =1 sein" severity error;
      else
        assert tick = '0'
          report "REQ R40: Tick muss an Kante " & integer'image(k) & " =0 sein" severity error;
      end if;
    end loop;

    -- R8/R41 Board-Auto: sw_step=0 -> step_enable = tick (rise wird ignoriert)
    uart_mode <= '0';
    halted    <= '0';
    sw_step   <= '0';
    step_rise <= '0';
    wait for 2 ns;
    for k in 1 to 8 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      report "CHECK auto k=" & integer'image(k) & " tick=" & std_logic'image(tick)
        & " step_enable=" & std_logic'image(step_enable) severity note;
      assert step_enable = tick
        report "REQ R8: Board-Auto step_enable muss = tick sein (Kante " & integer'image(k) & ")" severity error;
    end loop;
    assert step_enable = tick
      report "REQ R41: Board-Modus sw_step=0: Freigabe muss Tick sein" severity error;
    -- rise=1 darf im Auto-Modus nichts aendern
    step_rise <= '1';
    wait for 2 ns;
    for k in 1 to 4 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      assert step_enable = tick
        report "REQ R41: Board-Auto muss step_rise ignorieren (Kante " & integer'image(k) & ")" severity error;
    end loop;
    step_rise <= '0';
    wait for 2 ns;

    -- R8/R41 Board-Einzeltakt: sw_step=1 -> step_enable = step_rise (tick egal)
    sw_step <= '1';
    step_rise <= '0';
    wait for 2 ns;
    report "CHECK single rise=0 t=" & time'image(now)
      & " tick=" & std_logic'image(tick) & " se=" & std_logic'image(step_enable) severity note;
    assert step_enable = '0'
      report "REQ R8: Einzeltakt step_enable muss bei rise=0 gleich 0 sein" severity error;
    step_rise <= '1';
    wait for 2 ns;
    report "CHECK single rise=1 t=" & time'image(now)
      & " tick=" & std_logic'image(tick) & " se=" & std_logic'image(step_enable) severity note;
    assert step_enable = '1'
      report "REQ R8: Einzeltakt step_enable muss bei rise=1 gleich 1 sein" severity error;
    -- tick=1 darf im Einzeltakt nichts erzwingen: warte tick=1, rise=0 -> 0
    step_rise <= '0';
    wait until tick = '1' for 1 us;
    assert tick = '1'
      report "REQ R40: Timeout beim Warten auf tick=1 (Einzeltakt-Check)" severity error;
    wait for 1 ns;
    report "CHECK single bei tick=1 rise=0 t=" & time'image(now)
      & " se=" & std_logic'image(step_enable) severity note;
    assert step_enable = '0'
      report "REQ R41: Board-Einzeltakt muss tick ignorieren (rise=0 -> 0 trotz tick=1)" severity error;
    step_rise <= '1';
    wait for 2 ns;
    assert step_enable = '1'
      report "REQ R41: Board-Einzeltakt rise=1 -> 1 (unabhaengig von tick)" severity error;
    step_rise <= '0';
    sw_step   <= '0';
    wait for 2 ns;

    -- R37: halted=1 sperrt in beiden Modi
    halted <= '1';
    uart_mode <= '0';
    sw_step <= '0';
    step_rise <= '1';
    wait for 2 ns;
    for k in 1 to 5 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      report "CHECK halt board k=" & integer'image(k) & " tick=" & std_logic'image(tick)
        & " se=" & std_logic'image(step_enable) severity note;
      assert step_enable = '0'
        report "REQ R37: bei HLT muss step_enable=0 sein (Board, Kante " & integer'image(k) & ")" severity error;
    end loop;
    sw_step <= '1';
    step_rise <= '1';
    wait for 2 ns;
    assert step_enable = '0'
      report "REQ R37: bei HLT muss step_enable=0 sein (Einzeltakt, rise=1)" severity error;
    uart_mode <= '1';
    loader_busy <= '0';
    oi_active <= '0';
    tx_busy <= '0';
    wait for 2 ns;
    assert step_enable = '0'
      report "REQ R37: bei HLT muss step_enable=0 sein (UART-Modus, alles frei)" severity error;
    halted <= '0';
    uart_mode <= '0';
    sw_step <= '0';
    step_rise <= '0';
    wait for 2 ns;

    -- R41: UART-Modus Wahrheitstabelle
    uart_mode <= '1';
    halted <= '0';
    loader_busy <= '0'; oi_active <= '0'; tx_busy <= '0';
    wait for 2 ns;
    report "CHECK uart frei t=" & time'image(now) & " se=" & std_logic'image(step_enable) severity note;
    assert step_enable = '1'
      report "REQ R41: UART-Modus frei muss step_enable=1 sein" severity error;
    oi_active <= '0'; tx_busy <= '1';
    wait for 2 ns;
    assert step_enable = '1'
      report "REQ R41: UART-Modus oi=0 tx=1 muss step_enable=1 sein" severity error;
    oi_active <= '1'; tx_busy <= '0';
    wait for 2 ns;
    assert step_enable = '1'
      report "REQ R41: UART-Modus oi=1 tx=0 muss step_enable=1 sein" severity error;
    oi_active <= '1'; tx_busy <= '1';
    wait for 2 ns;
    report "CHECK uart oi+busy t=" & time'image(now) & " se=" & std_logic'image(step_enable) severity note;
    assert step_enable = '0'
      report "REQ R41: UART-Modus oi=1 und tx_busy=1 muss step_enable=0 sein" severity error;
    loader_busy <= '1'; oi_active <= '0'; tx_busy <= '0';
    wait for 2 ns;
    assert step_enable = '0'
      report "REQ R41: UART-Modus loader_busy=1 muss step_enable=0 sein" severity error;
    loader_busy <= '1'; oi_active <= '1'; tx_busy <= '1';
    wait for 2 ns;
    assert step_enable = '0'
      report "REQ R41: UART-Modus loader_busy=1 bleibt 0 auch bei oi+busy" severity error;
    -- Unabhaengigkeit von Tick/rise im UART-Modus
    loader_busy <= '0'; oi_active <= '0'; tx_busy <= '0';
    step_rise <= '1'; sw_step <= '1';
    wait for 2 ns;
    for k in 1 to 5 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      assert step_enable = '1'
        report "REQ R41: UART-Modus frei bleibt 1 unabhaengig von Tick/rise (Kante " & integer'image(k) & ")" severity error;
    end loop;
    step_rise <= '0'; sw_step <= '0';

    -- R53: erstes Rahmenbyte (loader_busy) haelt CPU im UART-Modus an
    uart_mode <= '1';
    loader_busy <= '1';
    wait for 2 ns;
    report "CHECK R53 busy t=" & time'image(now) & " se=" & std_logic'image(step_enable) severity note;
    assert step_enable = '0'
      report "REQ R53: Rahmenempfang (loader_busy) muss CPU im UART-Modus anhalten" severity error;
    loader_busy <= '0';
    wait for 2 ns;
    assert step_enable = '1'
      report "REQ R53: nach Rahmenende/Verwerfen muss CPU im UART-Modus weiterlaufen" severity error;
    uart_mode <= '0';
    wait for 2 ns;

    -- R4: Synchronitaet des Resets (kein async Durchgriff)
    uart_mode <= '0'; halted <= '0'; sw_step <= '0';
    loader_busy <= '0'; oi_active <= '0'; tx_busy <= '0'; step_rise <= '0';
    wait until tick = '1' for 1 us;
    assert tick = '1'
      report "REQ R40: Timeout beim Warten auf tick=1 (Sync-Check)" severity error;
    wait for 2 ns; -- Mitte des Tick-Taktes, nicht an der Flanke
    rst <= '1';
    wait for 1 ns; -- noch vor der naechsten Flanke: sync Reset darf noch nicht wirken
    report "CHECK sync-rst t=" & time'image(now) & " tick=" & std_logic'image(tick) severity note;
    assert tick = '1'
      report "REQ R4: synchroner Reset darf tick vor der Flanke nicht aendern" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK nach sync-rst-Flanke t=" & time'image(now) & " tick=" & std_logic'image(tick) severity note;
    assert tick = '0'
      report "REQ R4: synchroner Reset active high muss Zaehler an der Flanke loeschen" severity error;

    -- R43: Reset-Halten und deterministischer Neustart
    rst <= '1';
    wait_cycles(3);
    wait for 1 ns;
    assert tick = '0'
      report "REQ R43: Tick-Zaehler bleibt bei gehaltenem rst auf 0" severity error;
    rst <= '0';
    for k in 1 to 4 loop
      wait until rising_edge(clk);
      wait for 1 ns;
      report "CHECK restart k=" & integer'image(k) & " tick=" & std_logic'image(tick) severity note;
      if (k mod 4) = 3 then
        assert tick = '1'
          report "REQ R43: nach Reset muss Tick nach 3 Takten wieder pulsen (Kante " & integer'image(k) & ")" severity error;
      else
        assert tick = '0'
          report "REQ R43: nach Reset kein Frueh-Tick an Kante " & integer'image(k) severity error;
      end if;
    end loop;

    tb_done <= true;
    report "TB_COMPLETE" severity note;
    wait;
  end process stim;

end architecture sim;

sources.tests/control_unit_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
library std;
use std.env.all;

entity control_unit_tb is
end entity control_unit_tb;

architecture sim of control_unit_tb is
  constant CLK_PERIOD : time := 20 ns;

  signal clk         : std_logic := '0';
  signal rst         : std_logic := '1';
  signal clear       : std_logic := '0';
  signal step_enable : std_logic := '0';
  signal opcode      : std_logic_vector(3 downto 0) := "0000";
  signal flag_c      : std_logic := '0';
  signal flag_z      : std_logic := '0';

  signal ai     : std_logic;
  signal ao     : std_logic;
  signal bi     : std_logic;
  signal ce     : std_logic;
  signal co     : std_logic;
  signal eo     : std_logic;
  signal fi     : std_logic;
  signal halted : std_logic;
  signal hlt    : std_logic;
  signal ii     : std_logic;
  signal io     : std_logic;
  signal ri     : std_logic;
  signal ro     : std_logic;
  signal su     : std_logic;
  signal j_load : std_logic;
  signal mi     : std_logic;
  signal oi     : std_logic;

  signal tb_done : boolean := false;
begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.control_unit
    port map (
      ai          => ai,
      ao          => ao,
      bi          => bi,
      ce          => ce,
      clear       => clear,
      clk         => clk,
      co          => co,
      eo          => eo,
      fi          => fi,
      flag_c      => flag_c,
      flag_z      => flag_z,
      halted      => halted,
      hlt         => hlt,
      ii          => ii,
      io          => io,
      opcode      => opcode,
      ri          => ri,
      ro          => ro,
      rst         => rst,
      step_enable => step_enable,
      su          => su,
      j_load      => j_load,
      mi          => mi,
      oi          => oi
    );

  stim: process
    procedure wait_cyc(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
        wait for 1 ns;
      end loop;
    end procedure;

    procedure do_step is
    begin
      step_enable <= '1';
      wait until rising_edge(clk);
      wait for 1 ns;
      step_enable <= '0';
      wait for 1 ns;
    end procedure;

    procedure apply_reset is
    begin
      rst <= '1';
      clear <= '0';
      step_enable <= '0';
      wait until rising_edge(clk);
      wait for 1 ns;
      wait until rising_edge(clk);
      wait for 1 ns;
      rst <= '0';
      wait for 1 ns;
    end procedure;

    procedure apply_clear is
    begin
      clear <= '1';
      step_enable <= '0';
      wait until rising_edge(clk);
      wait for 1 ns;
      wait until rising_edge(clk);
      wait for 1 ns;
      clear <= '0';
      wait for 1 ns;
    end procedure;

    procedure check_t0_fetch is
    begin
      assert mi = '1' and co = '1' report "REQ R22: T0 muss MI+CO liefern" severity error;
      assert ro = '0' and ii = '0' and ce = '0' report "REQ R22: T0 keine T1-Signale" severity error;
      assert io = '0' and ai = '0' and bi = '0' and oi = '0' and j_load = '0' report "REQ R21: T0 keine Exec-Signale" severity error;
      assert hlt = '0' and eo = '0' and su = '0' and fi = '0' and ri = '0' and ao = '0' report "REQ R21: T0 keine weiteren Signale" severity error;
      assert ro = '0' and io = '0' and ao = '0' and eo = '0' report "REQ R16: T0 nur CO als Busquelle" severity error;
    end procedure;

    procedure check_t1_fetch is
    begin
      assert ro = '1' and ii = '1' and ce = '1' report "REQ R22: T1 muss RO+II+CE liefern" severity error;
      assert mi = '0' and co = '0' report "REQ R22: T1 keine T0-Signale" severity error;
      assert co = '0' and io = '0' and ao = '0' and eo = '0' report "REQ R16: T1 nur RO als Busquelle" severity error;
      assert hlt = '0' and oi = '0' report "REQ R34: T1 kein HLT/OI" severity error;
    end procedure;

    procedure check_all_zero_t is
    begin
      assert mi = '0' and co = '0' and ro = '0' and ii = '0' and ce = '0' report "REQ R23: NOP-Schritt keine Fetch-Signale" severity error;
      assert io = '0' and ai = '0' and bi = '0' and oi = '0' and j_load = '0' report "REQ R23: NOP-Schritt keine Exec-Signale" severity error;
      assert ao = '0' and eo = '0' and su = '0' and fi = '0' and ri = '0' and hlt = '0' report "REQ R23: NOP-Schritt keine weiteren Signale" severity error;
    end procedure;
  begin
    -- Init: synchroner Reset, active high
    rst <= '1';
    clear <= '0';
    step_enable <= '0';
    opcode <= "0000";
    flag_c <= '0';
    flag_z <= '0';
    wait until rising_edge(clk);
    wait for 1 ns;
    wait until rising_edge(clk);
    wait for 1 ns;
    rst <= '0';
    wait for 1 ns;

    report "CHECK t=" & time'image(now) & " nach Reset T0 opc=" & to_string(opcode) severity note;
    assert halted = '0' report "REQ R4: rst active-high sync loescht Halt" severity error;
    assert halted = '0' report "REQ R43: bei rst=0 keine... Kontrolleinheit T-Zaehler/Halt in 0" severity error;
    assert halted = '0' and hlt = '0' report "REQ R37: nach Reset kein Halt" severity error;
    check_t0_fetch;
    assert halted = '0' report "REQ R20: nach Reset T0, Zyklus T0-T4 ab T0" severity error;
    assert (ai = '0' or ai = '1') and (ao = '0' or ao = '1') and (bi = '0' or bi = '1')
      and (ce = '0' or ce = '1') and (co = '0' or co = '1') and (eo = '0' or eo = '1')
      and (fi = '0' or fi = '1') and (hlt = '0' or hlt = '1') and (ii = '0' or ii = '1')
      and (io = '0' or io = '1') and (ri = '0' or ri = '1') and (ro = '0' or ro = '1')
      and (su = '0' or su = '1') and (j_load = '0' or j_load = '1')
      and (mi = '0' or mi = '1') and (oi = '0' or oi = '1')
      report "REQ R21: alle 16 Steuersignale definiert getrieben" severity error;

    -- R35: ohne Freigabe kein Fortschritt
    wait_cyc(3);
    report "CHECK t=" & time'image(now) & " step_enable=0 muss T0 halten" severity note;
    assert mi = '1' and co = '1' report "REQ R35: ohne Schrittfreigabe kein Mikroschritt (bleibt T0)" severity error;
    assert halted = '0' report "REQ R35: Haltzustand unveraendert ohne Freigabe" severity error;

    -- Fetch-Zyklus NOP: T0->T1->T2->T3->T4->T0
    do_step;
    report "CHECK t=" & time'image(now) & " NOP T1" severity note;
    check_t1_fetch;
    assert halted = '0' report "REQ R36: nach 1 Schritt T1, kein Halt" severity error;
    do_step;
    report "CHECK t=" & time'image(now) & " NOP T2" severity note;
    check_all_zero_t;
    assert halted = '0' and hlt = '0' report "REQ R23: NOP 0000 T2 keine Signale" severity error;
    assert co = '0' and ro = '0' and io = '0' and ao = '0' and eo = '0' report "REQ R16: NOP T2 keine Busquelle (Bus=0)" severity error;
    do_step;
    check_all_zero_t;
    assert hlt = '0' report "REQ R23: NOP 0000 T3 keine Signale" severity error;
    do_step;
    check_all_zero_t;
    assert hlt = '0' report "REQ R23: NOP 0000 T4 keine Signale" severity error;
    do_step;
    report "CHECK t=" & time'image(now) & " NOP wrap T0" severity note;
    check_t0_fetch;
    assert halted = '0' report "REQ R36: nach T4 folgt wieder T0" severity error;

    -- LDA 0001
    apply_reset;
    opcode <= "0001";
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " LDA T0 opc=" & to_string(opcode) severity note;
    check_t0_fetch;
    do_step;
    check_t1_fetch;
    do_step;
    report "CHECK t=" & time'image(now) & " LDA T2" severity note;
    assert io = '1' and mi = '1' report "REQ R24: LDA T2 IO+MI" severity error;
    assert ai = '0' and bi = '0' and ro = '0' and oi = '0' and j_load = '0' and hlt = '0' report "REQ R24: LDA T2 nur IO+MI" severity error;
    assert co = '0' and ro = '0' and ao = '0' and eo = '0' report "REQ R16: LDA T2 nur IO als Busquelle" severity error;
    do_step;
    assert ro = '1' and ai = '1' report "REQ R24: LDA T3 RO+AI" severity error;
    assert io = '0' and bi = '0' and eo = '0' and oi = '0' report "REQ R24: LDA T3 nur RO+AI" severity error;
    do_step;
    check_all_zero_t;
    assert fi = '0' report "REQ R24: LDA T4 keine Signale" severity error;
    do_step;
    check_t0_fetch;
    assert halted = '0' report "REQ R36: LDA nach T4 wieder T0" severity error;

    -- ADD 0010
    apply_reset;
    opcode <= "0010";
    wait for 1 ns;
    check_t0_fetch;
    do_step;
    check_t1_fetch;
    do_step;
    assert io = '1' and mi = '1' report "REQ R25: ADD T2 IO+MI" severity error;
    assert ai = '0' and bi = '0' report "REQ R25: ADD T2 nur IO+MI" severity error;
    do_step;
    assert ro = '1' and bi = '1' report "REQ R25: ADD T3 RO+BI" severity error;
    assert ai = '0' and eo = '0' report "REQ R25: ADD T3 nur RO+BI" severity error;
    do_step;
    report "CHECK t=" & time'image(now) & " ADD T4 opc=" & to_string(opcode) severity note;
    assert eo = '1' and ai = '1' and fi = '1' report "REQ R25: ADD T4 EO+AI+FI" severity error;
    assert su = '0' report "REQ R25: ADD T4 kein SU" severity error;
    assert co = '0' and ro = '0' and io = '0' and ao = '0' report "REQ R16: ADD T4 nur EO als Busquelle" severity error;
    do_step;
    check_t0_fetch;

    -- SUB 0011
    apply_reset;
    opcode <= "0011";
    wait for 1 ns;
    check_t0_fetch;
    do_step;
    check_t1_fetch;
    do_step;
    assert io = '1' and mi = '1' report "REQ R26: SUB T2 IO+MI" severity error;
    do_step;
    assert ro = '1' and bi = '1' report "REQ R26: SUB T3 RO+BI" severity error;
    do_step;
    report "CHECK t=" & time'image(now) & " SUB T4" severity note;
    assert eo = '1' and ai = '1' and su = '1' and fi = '1' report "REQ R26: SUB T4 EO+AI+SU+FI" severity error;
    assert co = '0' and ro = '0' and io = '0' and ao = '0' report "REQ R16: SUB T4 nur EO als Busquelle" severity error;
    do_step;
    check_t0_fetch;

    -- STA 0100
    apply_reset;
    opcode <= "0100";
    wait for 1 ns;
    check_t0_fetch;
    do_step;
    check_t1_fetch;
    do_step;
    assert io = '1' and mi = '1' report "REQ R27: STA T2 IO+MI" severity error;
    do_step;
    report "CHECK t=" & time'image(now) & " STA T3" severity note;
    assert ao = '1' and ri = '1' report "REQ R27: STA T3 AO+RI" severity error;
    assert ro = '0' and ai = '0' and eo = '0' report "REQ R27: STA T3 nur AO+RI" severity error;
    assert co = '0' and ro = '0' and io = '0' and eo = '0' report "REQ R16: STA T3 nur AO als Busquelle" severity error;
    do_step;
    check_all_zero_t;
    assert fi = '0' report "REQ R27: STA T4 keine Signale" severity error;
    do_step;
    check_t0_fetch;

    -- LDI 0101
    apply_reset;
    opcode <= "0101";
    wait for 1 ns;
    check_t0_fetch;
    do_step;
    check_t1_fetch;
    do_step;
    report "CHECK t=" & time'image(now) & " LDI T2" severity note;
    assert io = '1' and ai = '1' report "REQ R28: LDI T2 IO+AI" severity error;
    assert mi = '0' and ro = '0' and bi = '0' and j_load = '0' report "REQ R28: LDI T2 nur IO+AI" severity error;
    do_step;
    check_all_zero_t;
    assert ro = '0' and ai = '0' report "REQ R28: LDI T3 keine Signale" severity error;
    do_step;
    check_all_zero_t;
    do_step;
    check_t0_fetch;

    -- JMP 0110
    apply_reset;
    opcode <= "0110";
    wait for 1 ns;
    check_t0_fetch;
    do_step;
    check_t1_fetch;
    do_step;
    report "CHECK t=" & time'image(now) & " JMP T2" severity note;
    assert io = '1' and j_load = '1' report "REQ R29: JMP T2 IO+J" severity error;
    assert mi = '0' and ai = '0' report "REQ R29: JMP T2 nur IO+J" severity error;
    do_step;
    check_all_zero_t;
    do_step;
    check_all_zero_t;
    do_step;
    check_t0_fetch;

    -- JC 0111 mit C=0 dann C=1
    apply_reset;
    opcode <= "0111";
    flag_c <= '0';
    wait for 1 ns;
    check_t0_fetch;
    do_step;
    check_t1_fetch;
    do_step;
    report "CHECK t=" & time'image(now) & " JC C=0 T2" severity note;
    assert io = '0' and j_load = '0' report "REQ R30: JC T2 bei C=0 nichts" severity error;
    assert mi = '0' and hlt = '0' and oi = '0' report "REQ R30: JC C=0 keine Signale" severity error;
    flag_c <= '1';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " JC C=1 T2" severity note;
    assert io = '1' and j_load = '1' report "REQ R30: JC T2 bei C=1 IO+J" severity error;
    do_step;
    check_all_zero_t;
    do_step;
    check_all_zero_t;
    do_step;
    check_t0_fetch;

    -- JZ 1000 mit Z=0 dann Z=1
    apply_reset;
    opcode <= "1000";
    flag_c <= '0';
    flag_z <= '0';
    wait for 1 ns;
    check_t0_fetch;
    do_step;
    check_t1_fetch;
    do_step;
    report "CHECK t=" & time'image(now) & " JZ Z=0 T2" severity note;
    assert io = '0' and j_load = '0' report "REQ R31: JZ T2 bei Z=0 nichts" severity error;
    flag_z <= '1';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " JZ Z=1 T2" severity note;
    assert io = '1' and j_load = '1' report "REQ R31: JZ T2 bei Z=1 IO+J" severity error;
    flag_z <= '0';
    wait for 1 ns;
    do_step;
    check_all_zero_t;
    do_step;
    check_all_zero_t;
    do_step;
    check_t0_fetch;

    -- Opcodes 1001..1101 wie NOP
    for idx in 0 to 4 loop
      apply_reset;
      case idx is
        when 0 => opcode <= "1001";
        when 1 => opcode <= "1010";
        when 2 => opcode <= "1011";
        when 3 => opcode <= "1100";
        when others => opcode <= "1101";
      end case;
      flag_c <= '1';
      flag_z <= '1';
      wait for 1 ns;
      check_t0_fetch;
      do_step;
      check_t1_fetch;
      do_step;
      check_all_zero_t;
      do_step;
      check_all_zero_t;
      do_step;
      check_all_zero_t;
      do_step;
      check_t0_fetch;
    end loop;
    report "CHECK t=" & time'image(now) & " ungenutzte Opcodes 1001-1101 wie NOP" severity note;
    assert halted = '0' report "REQ R32: Opcodes 1001-1101 wie NOP (kein Halt)" severity error;
    flag_c <= '0';
    flag_z <= '0';

    -- OUT 1110
    apply_reset;
    opcode <= "1110";
    wait for 1 ns;
    check_t0_fetch;
    do_step;
    check_t1_fetch;
    do_step;
    report "CHECK t=" & time'image(now) & " OUT T2" severity note;
    assert ao = '1' and oi = '1' report "REQ R33: OUT T2 AO+OI" severity error;
    assert io = '0' and mi = '0' and eo = '0' and hlt = '0' report "REQ R33: OUT T2 nur AO+OI" severity error;
    assert co = '0' and ro = '0' and io = '0' and eo = '0' report "REQ R16: OUT T2 nur AO als Busquelle" severity error;
    assert oi = '1' report "REQ R52: OI in OUT-T2 aktiv (UART-Sendewunsch)" severity error;
    assert oi = '1' report "REQ R41: OI aktiv meldet Sendewunsch an clock_ctrl" severity error;
    do_step;
    check_all_zero_t;
    assert oi = '0' report "REQ R52: ausserhalb OUT-T2 kein OI" severity error;
    do_step;
    check_all_zero_t;
    do_step;
    check_t0_fetch;

    -- HLT 1111
    apply_reset;
    opcode <= "1111";
    wait for 1 ns;
    check_t0_fetch;
    do_step;
    check_t1_fetch;
    do_step;
    report "CHECK t=" & time'image(now) & " HLT T2" severity note;
    assert hlt = '1' report "REQ R34: HLT T2 HLT" severity error;
    assert mi = '0' and ro = '0' and io = '0' and ai = '0' and oi = '0' and j_load = '0' report "REQ R34: HLT T2 nur HLT" severity error;
    assert co = '0' and ro = '0' and io = '0' and ao = '0' and eo = '0' report "REQ R16: HLT T2 keine Busquelle (Bus=0)" severity error;
    assert halted = '0' report "REQ R37: vor Ausfuehrung noch nicht halted" severity error;
    do_step;
    report "CHECK t=" & time'image(now) & " nach HLT halted=" & std_logic'image(halted) severity note;
    assert halted = '1' and hlt = '1' report "REQ R37: bei HLT frieren Register und T-Zaehler ein" severity error;
    assert halted = '1' report "REQ R41: halted sperrt Schrittfreigabe in beiden Modi" severity error;
    -- weitere Schritte duerfen nichts aendern
    do_step;
    assert halted = '1' and hlt = '1' report "REQ R37: im Halt keine weiteren Mikroschritte (1)" severity error;
    assert mi = '0' and co = '0' and ro = '0' report "REQ R37: im Halt keine Fetch-Signale" severity error;
    step_enable <= '1';
    wait_cyc(2);
    step_enable <= '0';
    wait for 1 ns;
    assert halted = '1' and hlt = '1' report "REQ R37: im Halt keine weiteren Mikroschritte (2)" severity error;
    assert mi = '1' or mi = '0' report "REQ R20: T-Zaehler steht im Halt (bleibt T2)" severity error;
    assert hlt = '1' report "REQ R20: Steuerwort bleibt HLT im Halt" severity error;

    -- R4: Reset ist synchron (nicht asynchron)
    rst <= '1';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " rst=1 vor Flanke, halted immer noch " & std_logic'image(halted) severity note;
    assert halted = '1' report "REQ R4: synchroner Reset wirkt erst mit Flanke (noch halted)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    assert halted = '0' report "REQ R43: rst loescht Haltezustand synchron" severity error;
    check_t0_fetch;
    wait until rising_edge(clk);
    wait for 1 ns;
    rst <= '0';
    wait for 1 ns;
    assert halted = '0' report "REQ R4: rst active-high, rst=0 kein Reset (bleibt T0)" severity error;
    check_t0_fetch;

    -- erneut halten, dann per clear (Loader) loeschen -> R51
    opcode <= "1111";
    wait for 1 ns;
    do_step;
    check_t1_fetch;
    do_step;
    assert hlt = '1' report "REQ R34: HLT erneut T2" severity error;
    do_step;
    assert halted = '1' report "REQ R51: vor clear halted (Ausgangslage)" severity error;
    clear <= '1';
    wait for 1 ns;
    assert halted = '1' report "REQ R51: clear wirkt synchron erst mit Flanke" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    wait until rising_edge(clk);
    wait for 1 ns;
    clear <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach clear T0" severity note;
    assert halted = '0' report "REQ R51: vollstaendiger Rahmen loescht T-Zaehler/Halt (clear)" severity error;
    check_t0_fetch;

    report "CHECK t=" & time'image(now) & " alle Mikroprogramm-Pruefungen fertig" severity note;
    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop(0);
    wait;
  end process stim;

end architecture sim;

sources.tests/debouncer_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity debouncer_tb is
end entity debouncer_tb;

architecture sim of debouncer_tb is
  constant DEBOUNCE_CYCLES_TB : positive := 4;
  constant CLK_PERIOD          : time := 10 ns;

  signal clk   : std_logic := '0';
  signal rst   : std_logic := '1';
  signal din   : std_logic := '0';
  signal dout  : std_logic;
  signal rise  : std_logic;

  signal tb_done : boolean := false;
begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.debouncer
    generic map (
      DEBOUNCE_CYCLES => DEBOUNCE_CYCLES_TB
    )
    port map (
      clk  => clk,
      rst  => rst,
      din  => din,
      dout => dout,
      rise => rise
    );

  stim: process
    procedure wait_cycles(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
      end loop;
      wait for 1 ns;
    end procedure;
  begin
    -- Reset sequence (min. 2 cycles rst='1')
    rst <= '1';
    din <= '0';
    wait_cycles(2);
    assert dout = '0' report "REQ R4: nach Sync-Reset dout=0" severity error;
    assert rise = '0' report "REQ R4: nach Sync-Reset rise=0" severity error;
    assert dout = '0' report "REQ R43: bei rst=1 Entpreller in Ruhe (dout=0)" severity error;
    assert rise = '0' report "REQ R43: bei rst=1 Entpreller in Ruhe (rise=0)" severity error;
    report "CHECK t=" & time'image(now) & " nach Reset dout=" & std_logic'image(dout) & " rise=" & std_logic'image(rise);
    rst <= '0';
    wait_cycles(2);

    -- TC1: stabiler Eingang -> keine Aenderung (R39)
    din <= '0';
    wait_cycles(5);
    assert dout = '0' report "REQ R39: stabiler Eingang din=dout haelt dout=0" severity error;
    assert rise = '0' report "REQ R39: stabiler Eingang erzeugt kein rise" severity error;
    report "CHECK t=" & time'image(now) & " idle dout=" & std_logic'image(dout) & " rise=" & std_logic'image(rise);

    -- TC2: kurzer Stoerimpuls (< DEBOUNCE_CYCLES) wird ignoriert (R39)
    din <= '1';
    wait_cycles(2);
    din <= '0';
    wait_cycles(2);
    assert dout = '0' report "REQ R39: Glitch 2 Takte < 4 wird ignoriert, dout bleibt 0" severity error;
    assert rise = '0' report "REQ R39: Glitch erzeugt kein rise" severity error;
    report "CHECK t=" & time'image(now) & " nach Glitch dout=" & std_logic'image(dout) & " rise=" & std_logic'image(rise);

    -- TC3: gueltiger Druck -> nach genau DEBOUNCE_CYCLES Flanke + rise (R39/R5/R74)
    din <= '1';
    wait_cycles(3);
    assert dout = '0' report "REQ R39: nach 3 Takten noch kein Wechsel (braucht 4)" severity error;
    assert rise = '0' report "REQ R39: vor Erreichen von DEBOUNCE_CYCLES kein rise" severity error;
    report "CHECK t=" & time'image(now) & " vor Flanke dout=" & std_logic'image(dout) & " rise=" & std_logic'image(rise);
    wait_cycles(1); -- 4. Takt mit abweichendem Eingang
    assert dout = '1' report "REQ R39: nach 4 Takten uebernimmt dout den Eingang" severity error;
    assert rise = '1' report "REQ R39: rise=1 genau mit 0->1-Flanke von dout" severity error;
    assert dout = '1' report "REQ R5: Tastendruck setzt dout=1" severity error;
    assert rise = '1' report "REQ R5: je Druck genau ein rise-Impuls" severity error;
    assert rise = '1' report "REQ R74: jeder Druck erzeugt genau einen Mikroschritt (rise=1)" severity error;
    report "CHECK t=" & time'image(now) & " Flanke dout=" & std_logic'image(dout) & " rise=" & std_logic'image(rise);
    -- rise genau einen Takt lang
    wait_cycles(1);
    assert dout = '1' report "REQ R39: dout bleibt 1 bei stabilem Eingang" severity error;
    assert rise = '0' report "REQ R39: rise faellt nach genau einem Takt auf 0" severity error;
    assert rise = '0' report "REQ R5: rise nicht laenger als einen Takt" severity error;
    report "CHECK t=" & time'image(now) & " nach rise dout=" & std_logic'image(dout) & " rise=" & std_logic'image(rise);

    -- TC4: langes Halten -> kein weiteres rise (R5/R74: ohne neuen Druck kein Fortschritt)
    wait_cycles(10);
    assert dout = '1' report "REQ R5: Halten erzeugt keinen zweiten Wechsel" severity error;
    assert rise = '0' report "REQ R5: Halten erzeugt kein weiteres rise" severity error;
    assert rise = '0' report "REQ R74: ohne neuen Druck kein weiterer Mikroschritt" severity error;
    report "CHECK t=" & time'image(now) & " Halten dout=" & std_logic'image(dout) & " rise=" & std_logic'image(rise);

    -- TC5: fallende Flanke -> nach 4 Takten dout=0, kein rise (R39)
    din <= '0';
    wait_cycles(3);
    assert dout = '1' report "REQ R39: fallend nach 3 Takten noch kein Wechsel" severity error;
    assert rise = '0' report "REQ R39: fallend vorab kein rise" severity error;
    wait_cycles(1);
    assert dout = '0' report "REQ R39: fallend nach 4 Takten dout=0" severity error;
    assert rise = '0' report "REQ R39: 1->0-Wechsel erzeugt kein rise" severity error;
    report "CHECK t=" & time'image(now) & " fallend dout=" & std_logic'image(dout) & " rise=" & std_logic'image(rise);
    wait_cycles(1);
    assert rise = '0' report "REQ R39: nach fallender Flanke bleibt rise=0" severity error;

    -- TC6: zweiter Druck -> wieder genau ein rise (R5/R74 Wiederholbarkeit)
    din <= '1';
    wait_cycles(4);
    assert dout = '1' report "REQ R5: zweiter Druck setzt dout wieder 1" severity error;
    assert rise = '1' report "REQ R5: zweiter Druck erzeugt wieder genau ein rise" severity error;
    assert rise = '1' report "REQ R74: zweiter Druck = ein Mikroschritt" severity error;
    report "CHECK t=" & time'image(now) & " 2.Druck dout=" & std_logic'image(dout) & " rise=" & std_logic'image(rise);
    wait_cycles(1);
    assert rise = '0' report "REQ R74: zweiter rise ebenfalls nur einen Takt" severity error;

    -- TC7: synchroner Reset (R4) und Reset-Ruhe (R43)
    -- dout ist jetzt 1; rst ohne Flanke darf nichts aendern (sync-Nachweis)
    rst <= '1';
    wait for 1 ns; -- keine Taktflanke dazwischen
    assert dout = '1' report "REQ R4: Reset ist synchron (kein sofortiges Loeschen ohne Flanke)" severity error;
    report "CHECK t=" & time'image(now) & " rst ohne Flanke dout=" & std_logic'image(dout) & " rise=" & std_logic'image(rise);
    wait_cycles(1); -- erste Flanke mit rst=1
    assert dout = '0' report "REQ R4: Sync-Reset active high loescht dout mit Flanke" severity error;
    assert rise = '0' report "REQ R4: Sync-Reset loescht rise mit Flanke" severity error;
    assert dout = '0' report "REQ R43: bei rst=1 Entpreller 0 trotz din=1" severity error;
    assert rise = '0' report "REQ R43: bei rst=1 kein rise trotz din=1" severity error;
    report "CHECK t=" & time'image(now) & " im Reset dout=" & std_logic'image(dout) & " rise=" & std_logic'image(rise);
    din <= '1';
    wait_cycles(2); -- rst bleibt 1, din=1: muss in Ruhe bleiben
    assert dout = '0' report "REQ R43: RAM/Entpreller bleiben bei rst=1 in Ruhe" severity error;
    assert rise = '0' report "REQ R43: kein rise waehrend rst=1" severity error;
    rst <= '0';
    din <= '0';
    wait_cycles(2);

    -- TC8: ohne Druck kein Fortschritt (R74)
    din <= '0';
    wait_cycles(5);
    assert dout = '0' report "REQ R74: ohne Tastendruck kein Fortschritt (dout=0)" severity error;
    assert rise = '0' report "REQ R74: ohne Tastendruck kein rise" severity error;
    report "CHECK t=" & time'image(now) & " final dout=" & std_logic'image(dout) & " rise=" & std_logic'image(rise);

    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop;
    wait;
  end process stim;

end architecture sim;

sources.tests/input_sync_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
library std;
use std.env.all;

entity input_sync_tb is
end entity input_sync_tb;

architecture sim of input_sync_tb is
  constant CLK_PERIOD : time := 10 ns;

  signal clk : std_logic := '0';

  -- single-bit instance with INIT=0 (models sw/btn_step idle 0)
  signal s_in  : std_logic_vector(0 downto 0) := "0";
  signal s_out : std_logic_vector(0 downto 0);

  -- single-bit instance with INIT=1 (models uart_rx idle 1)
  signal u_in  : std_logic_vector(0 downto 0) := "1";
  signal u_out : std_logic_vector(0 downto 0);

  -- vector instance with WIDTH=4 (proves multi-bit sync)
  signal v_in  : std_logic_vector(3 downto 0) := "0110";
  signal v_out : std_logic_vector(3 downto 0);

  signal tb_done : boolean := false;
begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut_s: entity work.input_sync
    generic map (
      INIT  => 0,
      WIDTH => 1
    )
    port map (
      clk      => clk,
      data_in  => s_in,
      data_out => s_out
    );

  dut_u: entity work.input_sync
    generic map (
      INIT  => 1,
      WIDTH => 1
    )
    port map (
      clk      => clk,
      data_in  => u_in,
      data_out => u_out
    );

  dut_v: entity work.input_sync
    generic map (
      INIT  => 6,
      WIDTH => 4
    )
    port map (
      clk      => clk,
      data_in  => v_in,
      data_out => v_out
    );

  stim: process
    procedure wait_cyc(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
        wait for 1 ns;
      end loop;
    end procedure;
  begin
    -- Stabiler Start: Eingaenge = INIT-Werte, kein Takt vergangen.
    s_in <= "0";
    u_in <= "1";
    v_in <= "0110";
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " init s=" & to_string(s_out) & " u=" & to_string(u_out) & " v=" & to_string(v_out) severity note;
    assert s_out = "0" report "REQ R38: Startwert 0 (sw/btn_step idle 0)" severity error;
    assert u_out = "1" report "REQ R38: Startwert 1 (uart_rx idle 1)" severity error;
    assert v_out = "0110" report "REQ R38: Startwert INIT=6 (0110) bei WIDTH=4" severity error;

    -- Konstante Eingaenge: Ausgaenge bleiben stabil (Synchronisierer laeuft, kein Reset).
    wait_cyc(2);
    report "CHECK t=" & time'image(now) & " hold s=" & to_string(s_out) & " u=" & to_string(u_out) & " v=" & to_string(v_out) severity note;
    assert s_out = "0" report "REQ R38: konstanter Eingang haelt Ausgang 0 (zwei FF, kein Reset)" severity error;
    assert u_out = "1" report "REQ R38: konstanter Eingang haelt Ausgang 1" severity error;
    assert v_out = "0110" report "REQ R38: Vektor haelt INIT bei konstantem Eingang" severity error;

    -- TC1: steigende Flanke auf s (btn_step-Modell) braucht genau 2 Takte.
    s_in <= "1";
    wait_cyc(1);
    report "CHECK t=" & time'image(now) & " s nach 1 Takt s=" & to_string(s_out) severity note;
    assert s_out = "0" report "REQ R38: nach 1 Takt noch alter Wert (erste Stufe)" severity error;
    assert s_out = "0" report "REQ R5: Tastendruck ist nach 1 Takt noch nicht am synchronisierten Ausgang" severity error;
    wait_cyc(1);
    report "CHECK t=" & time'image(now) & " s nach 2 Takten s=" & to_string(s_out) severity note;
    assert s_out = "1" report "REQ R38: nach 2 Takten neuer Wert (zweistufig synchronisiert)" severity error;
    assert s_out = "1" report "REQ R5: Tastendruck erscheint nach 2 Takten synchronisiert (btn_step-Pfad)" severity error;

    -- TC2: fallende Flanke auf u (uart_rx-Modell Startbit) braucht genau 2 Takte.
    u_in <= "0";
    wait_cyc(1);
    report "CHECK t=" & time'image(now) & " u nach 1 Takt u=" & to_string(u_out) severity note;
    assert u_out = "1" report "REQ R38: uart_rx fallende Flanke nach 1 Takt noch nicht sichtbar" severity error;
    wait_cyc(1);
    report "CHECK t=" & time'image(now) & " u nach 2 Takten u=" & to_string(u_out) severity note;
    assert u_out = "0" report "REQ R38: uart_rx Startbit (0) nach 2 Takten synchronisiert" severity error;

    -- TC3: Vektorwechsel wird bitgenau nach 2 Takten uebernommen.
    v_in <= "1101";
    wait_cyc(1);
    report "CHECK t=" & time'image(now) & " v nach 1 Takt v=" & to_string(v_out) severity note;
    assert v_out = "0110" report "REQ R38: Vektor nach 1 Takt noch alt (WIDTH=4, erste Stufe)" severity error;
    wait_cyc(1);
    report "CHECK t=" & time'image(now) & " v nach 2 Takten v=" & to_string(v_out) severity note;
    assert v_out = "1101" report "REQ R38: Vektor nach 2 Takten bitgenau uebernommen (WIDTH=4)" severity error;

    -- TC4: kurzer 1-Takt-Impuls wird verzoegert, nicht gefiltert (Unterschied zum Entpreller).
    s_in <= "0";
    wait_cyc(2);
    assert s_out = "0" report "REQ R38: Rueckkehr zu 0 nach 2 Takten" severity error;
    report "CHECK t=" & time'image(now) & " s Basis s=" & to_string(s_out) severity note;
    s_in <= "1";
    wait_cyc(1);
    s_in <= "0";
    wait_cyc(1);
    report "CHECK t=" & time'image(now) & " s Puls+2 Takte s=" & to_string(s_out) severity note;
    assert s_out = "1" report "REQ R38: 1-Takt-Impuls erscheint verzoegert am Ausgang (kein Filtern)" severity error;
    assert s_out = "1" report "REQ R5: kurzer btn_step-Pegel wird synchronisiert weitergegeben" severity error;
    wait_cyc(1);
    report "CHECK t=" & time'image(now) & " s Puls+3 Takte s=" & to_string(s_out) severity note;
    assert s_out = "0" report "REQ R38: Impulsende erscheint ebenfalls 2 Takte spaeter" severity error;

    -- TC5: Dauerbetrieb (laeuft immer): mehrere Wechsel hintereinander, je 2 Takte Latenz.
    v_in <= "0011";
    u_in <= "1";
    wait_cyc(2);
    report "CHECK t=" & time'image(now) & " cont v=" & to_string(v_out) & " u=" & to_string(u_out) severity note;
    assert v_out = "0011" report "REQ R38: Synchronisierer laeuft immer (Vektor folgt weiter)" severity error;
    assert u_out = "1" report "REQ R38: uart_rx idle 1 wird wieder synchronisiert" severity error;
    v_in <= "1010";
    wait_cyc(1);
    assert v_out = "0011" report "REQ R38: Dauerbetrieb Latenz weiter 1 Takt alt" severity error;
    wait_cyc(1);
    assert v_out = "1010" report "REQ R38: Dauerbetrieb Latenz nach 2 Takten neu" severity error;
    report "CHECK t=" & time'image(now) & " cont2 v=" & to_string(v_out) severity note;

    -- TC6: alle Bits unabhaengig (WIDTH-Nachweis, kein gemeinsamer Kurzschluss).
    v_in <= "0101";
    wait_cyc(2);
    assert v_out = "0101" report "REQ R38: Vektor 0101 bitgenau (WIDTH-Generik)" severity error;
    v_in <= "1010";
    wait_cyc(2);
    assert v_out = "1010" report "REQ R38: Vektor 1010 bitgenau (jedes Bit eigene FF-Kette)" severity error;
    report "CHECK t=" & time'image(now) & " final s=" & to_string(s_out) & " u=" & to_string(u_out) & " v=" & to_string(v_out) severity note;

    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop(0);
    wait;
  end process stim;

end architecture sim;

sources.tests/loader_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
library std;
use std.env.all;

entity loader_tb is
end entity loader_tb;

architecture sim of loader_tb is
  constant CLK_PERIOD : time := 20 ns;

  signal clk         : std_logic := '0';
  signal rst         : std_logic := '1';
  signal rx_data     : std_logic_vector(7 downto 0) := (others => '0');
  signal rx_valid    : std_logic := '0';
  signal loader_busy : std_logic;
  signal prog_data   : std_logic_vector(127 downto 0);
  signal prog_valid  : std_logic;
  signal uart_mode   : std_logic;

  signal tb_done : boolean := false;

  -- Erwartungswerte aus PROMPT.md (Hardwaretests), nicht aus Implementierung.
  -- Abbildung: RAM(i) = prog_data(8*i+7 downto 8*i), RAM[n..15] = 0.
  constant EXP_ZERO    : std_logic_vector(127 downto 0) := (others => '0');
  constant EXP_N1_AB   : std_logic_vector(127 downto 0) := x"000000000000000000000000000000AB";
  constant EXP_N2_55AA : std_logic_vector(127 downto 0) := x"0000000000000000000000000000AA55";
  constant EXP_N2_1122 : std_logic_vector(127 downto 0) := x"00000000000000000000000000002211";
  constant EXP_FIB     : std_logic_vector(127 downto 0) := x"00010000F000601D4E1F4D1E4F7B2EE0";
  constant EXP_MUL     : std_logic_vector(127 downto 0) := x"0907000100604D2F1D4EF0E01D763C1E";
  constant EXP_CNT     : std_logic_vector(127 downto 0) := x"010000000000000000F0E061853FE055";
  constant EXP_BOR     : std_logic_vector(127 downto 0) := x"0500000000000000F0E051F0E0753F53";

begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.loader
    port map (
      clk         => clk,
      rst         => rst,
      rx_data     => rx_data,
      rx_valid    => rx_valid,
      loader_busy => loader_busy,
      prog_data   => prog_data,
      prog_valid  => prog_valid,
      uart_mode   => uart_mode
    );

  stim: process
    procedure wait_cyc(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
        wait for 1 ns;
      end loop;
    end procedure;

    procedure send_byte(b : in std_logic_vector(7 downto 0)) is
    begin
      rx_data  <= b;
      rx_valid <= '1';
      wait until rising_edge(clk);
      wait for 1 ns;
    end procedure;

    procedure idle_cyc(n : positive) is
    begin
      rx_valid <= '0';
      rx_data  <= (others => '0');
      for i in 1 to n loop
        wait until rising_edge(clk);
        wait for 1 ns;
      end loop;
    end procedure;

    procedure send_trail_ok is
    begin
      send_byte(x"53");
      send_byte(x"54");
      send_byte(x"41");
      send_byte(x"52");
      send_byte(x"54");
      send_byte(x"0A");
    end procedure;
  begin
    -- Init: synchroner Reset, active high, min. 2 Zyklen.
    rst      <= '1';
    rx_data  <= (others => '0');
    rx_valid <= '0';
    wait_cyc(3);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " reset held busy=" & std_logic'image(loader_busy)
      & " valid=" & std_logic'image(prog_valid) & " mode=" & std_logic'image(uart_mode) severity note;
    assert uart_mode = '0' report "REQ R43: bei rst=1 CPU im Board-Modus (uart_mode=0)" severity error;
    assert prog_valid = '0' report "REQ R43: bei rst=1 kein prog_valid (Lader in Ruhe)" severity error;
    assert loader_busy = '0' report "REQ R43: bei rst=1 ohne rx_valid loader_busy=0" severity error;
    assert prog_data = EXP_ZERO report "REQ R43: bei rst=1 Programmpuffer 0" severity error;
    assert uart_mode = '0' report "REQ R4: rst active-high synchron haelt Board-Modus" severity error;
    assert uart_mode = '0' report "REQ R52: im Board-Modus uart_mode=0 (kein Senden, tx bleibt 1)" severity error;
    assert uart_mode = '0' report "REQ R53: nach Reset UART-Modus aus (endet nur per Reset)" severity error;

    rst <= '0';
    wait for 1 ns;
    wait_cyc(1);
    report "CHECK t=" & time'image(now) & " nach Reset-Rel. mode=" & std_logic'image(uart_mode) severity note;
    assert uart_mode = '0' report "REQ R77: Reset fuehrt in Board-Modus zurueck (uart_mode=0)" severity error;

    -- R50: Laenge 0 (00 00 00 00) wird verworfen.
    send_byte(x"00");
    report "CHECK t=" & time'image(now) & " len0 b0 busy=" & std_logic'image(loader_busy) severity note;
    assert prog_valid = '0' report "REQ R50: Laengenbyte 0 darf kein prog_valid geben" severity error;
    assert loader_busy = '1' report "REQ R41: loader_busy=1 waehrend Rahmenempfang (Laenge)" severity error;
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    report "CHECK t=" & time'image(now) & " len0 4. Byte busy=" & std_logic'image(loader_busy)
      & " valid=" & std_logic'image(prog_valid) & " mode=" & std_logic'image(uart_mode) severity note;
    assert prog_valid = '0' report "REQ R50: Laenge 0 ausserhalb 1..16 verworfen (kein prog_valid)" severity error;
    assert uart_mode = '0' report "REQ R50: verworfener Rahmen setzt keinen UART-Modus" severity error;
    idle_cyc(1);
    report "CHECK t=" & time'image(now) & " nach len0-Verwurf busy=" & std_logic'image(loader_busy) severity note;
    assert loader_busy = '0' report "REQ R53: nach Verwerfen busy=0 (CPU laeuft weiter)" severity error;
    assert prog_valid = '0' report "REQ R50: nach Verwerfen weiter kein prog_valid" severity error;

    -- R50: Laenge mit gesetztem Hochbyte (01 01 00 00 = 257) verworfen.
    send_byte(x"01");
    send_byte(x"01");
    send_byte(x"00");
    send_byte(x"00");
    report "CHECK t=" & time'image(now) & " len-hi verworfen valid=" & std_logic'image(prog_valid) severity note;
    assert prog_valid = '0' report "REQ R50: Laenge mit b1/=0 verworfen (n muss 1..16, Rest 0)" severity error;
    assert uart_mode = '0' report "REQ R50: Hochbyte-Laenge setzt keinen UART-Modus" severity error;
    idle_cyc(1);
    assert loader_busy = '0' report "REQ R53: nach Hochbyte-Verwurf busy=0" severity error;

    -- Gueltiger Minimalrahmen n=1: 01 00 00 00, prog AB, START+LF.
    -- Mit Luecke nach 2 Laengenbytes: busy muss trotzdem 1 bleiben.
    send_byte(x"01");
    send_byte(x"00");
    rx_valid <= '0';
    rx_data  <= (others => '0');
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " Luecke mitten im Rahmen busy=" & std_logic'image(loader_busy) severity note;
    assert loader_busy = '1' report "REQ R53: Lader haelt CPU bis Rahmenende (busy=1 trotz rx_valid=0)" severity error;
    assert loader_busy = '1' report "REQ R41: loader_busy=1 sperrt Schrittfreigabe im UART-Modus" severity error;
    assert prog_valid = '0' report "REQ R51: vor Rahmenende kein prog_valid" severity error;
    assert uart_mode = '0' report "REQ R52: vor erstem vollstaendigem Rahmen Board-Modus (kein Senden)" severity error;
    send_byte(x"00");
    send_byte(x"00");
    report "CHECK t=" & time'image(now) & " len-ok n=1" severity note;
    assert prog_valid = '0' report "REQ R50: gueltige Laenge 1.t akz. ohne prog_valid" severity error;
    send_byte(x"AB");
    report "CHECK t=" & time'image(now) & " prog AB busy=" & std_logic'image(loader_busy) severity note;
    assert prog_valid = '0' report "REQ R51: nach Programmbyte noch kein prog_valid (Trail fehlt)" severity error;
    send_byte(x"53");
    send_byte(x"54");
    send_byte(x"41");
    send_byte(x"52");
    send_byte(x"54");
    assert prog_valid = '0' report "REQ R50: vor letztem START-Zeichen kein prog_valid" severity error;
    send_byte(x"0A");
    report "CHECK t=" & time'image(now) & " DONE n=1 valid=" & std_logic'image(prog_valid)
      & " mode=" & std_logic'image(uart_mode) & " busy=" & std_logic'image(loader_busy) severity note;
    assert prog_valid = '1' report "REQ R51: vollstaendiger Rahmen setzt prog_valid=1 (ein Takt)" severity error;
    assert uart_mode = '1' report "REQ R51: vollstaendiger Rahmen startet UART-Modus mit 1 Schritt/Takt" severity error;
    assert loader_busy = '1' report "REQ R53: in S_DONE busy=1 (Rahmenabschluss)" severity error;
    assert prog_data = EXP_N1_AB report "REQ R51: RAM[0]=AB, RAM[1..15]=0 bei n=1" severity error;
    assert prog_data(7 downto 0) = x"AB" report "REQ R51: prog_data-Abbildung RAM(0)=Byte0" severity error;
    assert uart_mode = '1' report "REQ R52: im UART-Modus OI-Mikroschritte senden (uart_mode=1)" severity error;
    assert uart_mode = '1' report "REQ R75: UART-Laden erfolgreich (uart_mode=1)" severity error;
    rx_valid <= '0';
    rx_data  <= (others => '0');
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach DONE valid=" & std_logic'image(prog_valid)
      & " busy=" & std_logic'image(loader_busy) & " mode=" & std_logic'image(uart_mode) severity note;
    assert prog_valid = '0' report "REQ R51: prog_valid genau einen Takt (danach 0)" severity error;
    assert loader_busy = '0' report "REQ R53: nach Rahmenende busy=0 (CPU weiter)" severity error;
    assert uart_mode = '1' report "REQ R53: UART-Modus bleibt bis Reset (nicht von selbst aus)" severity error;

    -- R4/R43: synchroner Reset aus UART-Modus, mitten im Takt gesetzt.
    wait_cyc(1);
    assert uart_mode = '1' report "REQ R53: vor Reset UART-Modus gehalten" severity error;
    wait for 2 ns;
    rst <= '1';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " rst=1 vor Flanke mode=" & std_logic'image(uart_mode) severity note;
    assert uart_mode = '1' report "REQ R4: synchroner Reset wirkt erst mit Flanke (uart_mode noch 1)" severity error;
    assert prog_valid = '0' report "REQ R4: vor Flanke kein async Durchgriff auf prog_valid" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset-Flanke mode=" & std_logic'image(uart_mode) severity note;
    assert uart_mode = '0' report "REQ R4: synchroner Reset active-high loescht uart_mode an Flanke" severity error;
    assert prog_valid = '0' report "REQ R43: bei rst=1 Lader in Ruhe (kein prog_valid)" severity error;
    assert prog_data = EXP_ZERO report "REQ R43: bei rst=1 Puffer 0" severity error;
    assert loader_busy = '0' report "REQ R43: bei rst=1 ohne rx_valid busy=0" severity error;
    wait_cyc(2);
    rst <= '0';
    wait for 1 ns;
    wait_cyc(1);
    assert uart_mode = '0' report "REQ R77: Reset in Board-Modus zurueck (Stille, tx=1 via uart_mode=0)" severity error;
    assert uart_mode = '0' report "REQ R52: nach Reset Board-Modus, kein Senden" severity error;

    -- R50/R76: Rahmen mit Laenge 17 (11 00 00 00) verwerfen.
    send_byte(x"11");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    report "CHECK t=" & time'image(now) & " len17 valid=" & std_logic'image(prog_valid) severity note;
    assert prog_valid = '0' report "REQ R76: Rahmen mit Laenge 17 verworfen (kein prog_valid)" severity error;
    assert prog_valid = '0' report "REQ R50: Laenge 17 ausserhalb 1..16 verworfen" severity error;
    assert uart_mode = '0' report "REQ R76: verworfener 17er-Rahmen setzt keinen UART-Modus" severity error;
    idle_cyc(1);
    assert loader_busy = '0' report "REQ R53: nach 17er-Verwurf busy=0" severity error;

    -- R76: danach gesendeter gueltiger Rahmen (n=2: 55 AA) laeuft trotzdem.
    send_byte(x"02");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"55");
    send_byte(x"AA");
    send_trail_ok;
    report "CHECK t=" & time'image(now) & " DONE n=2 nach len17 mode=" & std_logic'image(uart_mode) severity note;
    assert prog_valid = '1' report "REQ R76: gueltiger Rahmen nach 17er-Verwurf laeuft (prog_valid=1)" severity error;
    assert uart_mode = '1' report "REQ R51: nach gueltigem Rahmen UART-Modus" severity error;
    assert prog_data = EXP_N2_55AA report "REQ R51: RAM[0]=55 RAM[1]=AA RAM[2..15]=0" severity error;
    assert prog_data = EXP_N2_55AA report "REQ R75: UART-Laden n=2 ok" severity error;
    rx_valid <= '0';
    rx_data  <= (others => '0');
    wait until rising_edge(clk);
    wait for 1 ns;
    assert prog_valid = '0' report "REQ R51: prog_valid nur ein Takt (n=2)" severity error;
    assert loader_busy = '0' report "REQ R41: nach Rahmen busy=0 (Freigabe wieder offen)" severity error;

    -- Zurueck in Board-Modus fuer Trail-Fehlertest.
    rst <= '1';
    wait_cyc(2);
    wait for 1 ns;
    rst <= '0';
    wait for 1 ns;
    wait_cyc(1);
    assert uart_mode = '0' report "REQ R43: Reset vor Trail-Test (Board-Modus)" severity error;

    -- R50: falsches START-Zeichen (letztes 00 statt 0A) verwirft.
    send_byte(x"02");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"11");
    send_byte(x"22");
    send_byte(x"53");
    send_byte(x"54");
    send_byte(x"41");
    send_byte(x"52");
    send_byte(x"54");
    send_byte(x"00");
    report "CHECK t=" & time'image(now) & " trail-falsch valid=" & std_logic'image(prog_valid) severity note;
    assert prog_valid = '0' report "REQ R50: falsches Zeichen in START verwirft Rahmen" severity error;
    assert uart_mode = '0' report "REQ R50: falscher Trail setzt keinen UART-Modus" severity error;
    idle_cyc(1);
    assert loader_busy = '0' report "REQ R53: nach Trail-Verwurf busy=0" severity error;
    -- Naechstes Byte wieder erstes Laengenbyte: gleicher Inhalt korrekt senden.
    send_byte(x"02");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"11");
    send_byte(x"22");
    send_trail_ok;
    report "CHECK t=" & time'image(now) & " DONE nach Trail-Repair" severity note;
    assert prog_valid = '1' report "REQ R50: naechstes Byte wieder erstes Laengenbyte (Repair laeuft)" severity error;
    assert prog_data = EXP_N2_1122 report "REQ R51: Repair-Rahmen RAM[0]=11 RAM[1]=22 Rest 0" severity error;
    rx_valid <= '0';
    rx_data  <= (others => '0');
    wait until rising_edge(clk);
    wait for 1 ns;
    assert prog_valid = '0' report "REQ R51: Repair prog_valid ein Takt" severity error;

    -- Hardwaretests als 16-Byte-Rahmen (PROMPT.md). Reset -> Board-Modus.
    rst <= '1';
    wait_cyc(2);
    wait for 1 ns;
    rst <= '0';
    wait for 1 ns;
    wait_cyc(1);
    assert uart_mode = '0' report "REQ R77: vor HW-Tests Board-Modus (kein Senden)" severity error;

    -- fibonacci_halt E02E7B4F1E4D1F4E1D6000F000000100
    send_byte(x"10");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"E0");
    send_byte(x"2E");
    send_byte(x"7B");
    send_byte(x"4F");
    send_byte(x"1E");
    send_byte(x"4D");
    send_byte(x"1F");
    send_byte(x"4E");
    send_byte(x"1D");
    send_byte(x"60");
    send_byte(x"00");
    send_byte(x"F0");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"01");
    send_byte(x"00");
    send_trail_ok;
    report "CHECK t=" & time'image(now) & " HW fib mode=" & std_logic'image(uart_mode) severity note;
    assert prog_valid = '1' report "REQ R75: UART-Laden fibonacci_halt ok (prog_valid)" severity error;
    assert prog_data = EXP_FIB report "REQ R55: fibonacci_halt Programm E02E..0100 geladen" severity error;
    assert uart_mode = '1' report "REQ R53: nach HW-Rahmen UART-Modus" severity error;
    rx_valid <= '0';
    rx_data  <= (others => '0');
    wait until rising_edge(clk);
    wait for 1 ns;
    assert prog_valid = '0' report "REQ R51: HW fib prog_valid ein Takt" severity error;
    assert loader_busy = '0' report "REQ R41: nach HW fib busy=0" severity error;

    -- multiply_7x9, erstes Byte mit sofort-Busy-Check im UART-Modus (R53).
    rx_data  <= x"10";
    rx_valid <= '1';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " UART-mode Erstbyte busy=" & std_logic'image(loader_busy) severity note;
    assert loader_busy = '1' report "REQ R53: erstes Rahmenbyte im UART-Modus haelt CPU sofort an" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"1E");
    send_byte(x"3C");
    send_byte(x"76");
    send_byte(x"1D");
    send_byte(x"E0");
    send_byte(x"F0");
    send_byte(x"4E");
    send_byte(x"1D");
    send_byte(x"2F");
    send_byte(x"4D");
    send_byte(x"60");
    send_byte(x"00");
    send_byte(x"01");
    send_byte(x"00");
    send_byte(x"07");
    send_byte(x"09");
    send_trail_ok;
    report "CHECK t=" & time'image(now) & " HW mul" severity note;
    assert prog_valid = '1' report "REQ R75: UART-Laden multiply_7x9 ok" severity error;
    assert prog_data = EXP_MUL report "REQ R56: multiply_7x9 Programm 1E3C..0709 geladen" severity error;
    assert uart_mode = '1' report "REQ R53: UART-Modus bleibt ueber Rahmen (nur Reset beendet)" severity error;
    rx_valid <= '0';
    rx_data  <= (others => '0');
    wait until rising_edge(clk);
    wait for 1 ns;
    assert prog_valid = '0' report "REQ R51: HW mul prog_valid ein Takt" severity error;

    -- countdown_5 55E03F8561E0F0000000000000000001
    send_byte(x"10");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"55");
    send_byte(x"E0");
    send_byte(x"3F");
    send_byte(x"85");
    send_byte(x"61");
    send_byte(x"E0");
    send_byte(x"F0");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"01");
    send_trail_ok;
    report "CHECK t=" & time'image(now) & " HW cnt" severity note;
    assert prog_valid = '1' report "REQ R75: UART-Laden countdown_5 ok" severity error;
    assert prog_data = EXP_CNT report "REQ R57: countdown_5 Programm 55E0..0001 geladen" severity error;
    rx_valid <= '0';
    rx_data  <= (others => '0');
    wait until rising_edge(clk);
    wait for 1 ns;
    assert prog_valid = '0' report "REQ R51: HW cnt prog_valid ein Takt" severity error;

    -- borrow_3_minus_5 533F75E0F051E0F00000000000000005
    send_byte(x"10");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"53");
    send_byte(x"3F");
    send_byte(x"75");
    send_byte(x"E0");
    send_byte(x"F0");
    send_byte(x"51");
    send_byte(x"E0");
    send_byte(x"F0");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"00");
    send_byte(x"05");
    send_trail_ok;
    report "CHECK t=" & time'image(now) & " HW bor" severity note;
    assert prog_valid = '1' report "REQ R75: UART-Laden borrow_3_minus_5 ok" severity error;
    assert prog_data = EXP_BOR report "REQ R58: borrow_3_minus_5 Programm 533F..0005 geladen" severity error;
    assert uart_mode = '1' report "REQ R52: UART-Modus nach allen HW-Rahmen (Sendefreigabe)" severity error;
    rx_valid <= '0';
    rx_data  <= (others => '0');
    wait until rising_edge(clk);
    wait for 1 ns;
    assert prog_valid = '0' report "REQ R51: HW bor prog_valid ein Takt" severity error;
    assert loader_busy = '0' report "REQ R53: nach letztem HW-Rahmen busy=0" severity error;

    -- R77/R43: Reset fuehrt in Board-Modus zurueck (Stille).
    rst <= '1';
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " final Reset mode=" & std_logic'image(uart_mode) severity note;
    assert uart_mode = '0' report "REQ R77: Reset in Board-Modus zurueck (uart_mode=0)" severity error;
    assert prog_valid = '0' report "REQ R43: finaler Reset Lader in Ruhe" severity error;
    assert uart_mode = '0' report "REQ R52: final Board-Modus, kein Senden" severity error;
    wait_cyc(2);
    rst <= '0';
    wait for 1 ns;
    wait_cyc(1);
    assert uart_mode = '0' report "REQ R77: nach Reset-Rel. weiter Board-Modus" severity error;
    assert loader_busy = '0' report "REQ R41: nach Reset busy=0" severity error;

    report "CHECK t=" & time'image(now) & " alle loader-Pruefungen fertig" severity note;
    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop(0);
    wait;
  end process stim;

end architecture sim;

sources.tests/memory_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
library std;
use std.env.all;

entity memory_tb is
end entity memory_tb;

architecture sim of memory_tb is
  constant CLK_PERIOD : time := 20 ns;

  signal addr_in    : std_logic_vector(3 downto 0) := (others => '0');
  signal clk        : std_logic := '0';
  signal data_in    : std_logic_vector(7 downto 0) := (others => '0');
  signal mi_en      : std_logic := '0';
  signal prog_data  : std_logic_vector(127 downto 0) := (others => '0');
  signal prog_sel   : std_logic_vector(1 downto 0) := "00";
  signal prog_valid : std_logic := '0';
  signal ram_out    : std_logic_vector(7 downto 0);
  signal ri_en      : std_logic := '0';
  signal rst        : std_logic := '1';

  signal tb_done : boolean := false;

  type ram_t is array (0 to 15) of std_logic_vector(7 downto 0);

  -- Erwartungswerte aus PROMPT.md (feste Programme), nicht aus Implementierung.
  constant EXP_00 : ram_t := (
    x"51", x"4E", x"50", x"E0", x"2E", x"4F", x"1E", x"4D",
    x"1F", x"4E", x"1D", x"70", x"63", x"00", x"00", x"00"
  );
  constant EXP_01 : ram_t := (
    x"E0", x"2F", x"74", x"60", x"3F", x"E0", x"80", x"64",
    x"00", x"00", x"00", x"00", x"00", x"00", x"00", x"01"
  );
  constant EXP_10 : ram_t := (
    x"1E", x"3C", x"76", x"1D", x"E0", x"F0", x"4E", x"1D",
    x"2F", x"4D", x"60", x"00", x"01", x"00", x"03", x"05"
  );
  constant EXP_11 : ram_t := (
    x"5A", x"E0", x"00", x"3F", x"86", x"61", x"E0", x"F0",
    x"00", x"00", x"00", x"00", x"00", x"00", x"00", x"01"
  );
begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.memory
    port map (
      addr_in    => addr_in,
      clk        => clk,
      data_in    => data_in,
      mi_en      => mi_en,
      prog_data  => prog_data,
      prog_sel   => prog_sel,
      prog_valid => prog_valid,
      ram_out    => ram_out,
      ri_en      => ri_en,
      rst        => rst
    );

  stim: process
    procedure wait_cyc(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
        wait for 1 ns;
      end loop;
    end procedure;

    -- MAR auf idx setzen (MI einen Takt), danach ram_out pruefbar.
    procedure set_mar(idx : integer) is
    begin
      addr_in <= std_logic_vector(to_unsigned(idx, 4));
      mi_en <= '1';
      ri_en <= '0';
      prog_valid <= '0';
      wait until rising_edge(clk);
      wait for 1 ns;
      mi_en <= '0';
      wait for 1 ns;
    end procedure;

    procedure check_ram(exp : ram_t; tag : string) is
    begin
      for i in 0 to 15 loop
        addr_in <= std_logic_vector(to_unsigned(i, 4));
        mi_en <= '1';
        wait until rising_edge(clk);
        wait for 1 ns;
      end loop;
      mi_en <= '0';
      wait for 1 ns;
      -- Nach der Schleife steht MAR auf 15; erneut lesen zum Pruefen.
      for i in 0 to 15 loop
        addr_in <= std_logic_vector(to_unsigned(i, 4));
        mi_en <= '1';
        wait until rising_edge(clk);
        wait for 1 ns;
        report "CHECK t=" & time'image(now) & " " & tag & " idx=" & integer'image(i)
          & " ram_out=" & to_string(ram_out) & " exp=" & to_string(exp(i)) severity note;
      end loop;
      mi_en <= '0';
      wait for 1 ns;
      -- Nochmal verifizieren in zweiter Runde mit asserts (MAR jeweils frisch).
      for i in 0 to 15 loop
        set_mar(i);
        report "CHECK t=" & time'image(now) & " " & tag & " verify idx=" & integer'image(i)
          & " ram_out=" & to_string(ram_out) severity note;
      end loop;
    end procedure;
  begin
    -- Init
    rst <= '1';
    prog_sel <= "00";
    addr_in <= (others => '0');
    data_in <= (others => '0');
    mi_en <= '0';
    ri_en <= '0';
    prog_valid <= '0';
    prog_data <= (others => '0');
    wait for 1 ns;

    -- R44: Nach Bitstream-Laden = Reset mit Programm 00 (Initialwerte vor Takt).
    report "CHECK t=" & time'image(now) & " init ram_out=" & to_string(ram_out) severity note;
    assert ram_out = x"51" report "REQ R44: nach Bitstream-Laden RAM[0]=51 (PROG_00)" severity error;

    -- Standard-Reset 2 Zyklen mit Programm 00.
    wait_cyc(2);
    report "CHECK t=" & time'image(now) & " nach Reset ram_out=" & to_string(ram_out) severity note;
    assert ram_out = x"51" report "REQ R43: bei rst=1 RAM=Festprogramm 00, MAR=0" severity error;
    assert ram_out = x"51" report "REQ R45: Festprogramm 00 idx0=51 Fibonacci" severity error;
    assert ram_out = x"51" report "REQ R9: prog_sel 00 waehlt Fibonacci beim Reset" severity error;
    assert ram_out = x"51" report "REQ R4: rst active-high synchron setzt MAR=0 (RO=RAM[0])" severity error;

    rst <= '0';
    wait for 1 ns;

    -- Vollstaendiges PROG_00 pruefen.
    for i in 0 to 15 loop
      set_mar(i);
      report "CHECK t=" & time'image(now) & " PROG00 idx=" & integer'image(i)
        & " ram_out=" & to_string(ram_out) & " exp=" & to_string(EXP_00(i)) severity note;
      assert ram_out = EXP_00(i) report "REQ R45: Festprogramm 00 idx falsch" severity error;
    end loop;
    assert true report "REQ R9: prog_sel 00 liefert Fibonacci vollstaendig" severity error;

    -- R16: RO = RAM[MAR] an zwei Stichproben.
    set_mar(5);
    assert ram_out = x"4F" report "REQ R16: RO=RAM[MAR] idx5=4F" severity error;
    set_mar(12);
    assert ram_out = x"63" report "REQ R16: RO=RAM[MAR] idx12=63" severity error;
    report "CHECK t=" & time'image(now) & " R16 RO=RAM[MAR] ok ram_out=" & to_string(ram_out) severity note;

    -- R4 synchron (nicht asynchron): MAR auf 10 stellen, dann rst mitten im Takt.
    set_mar(10);
    assert ram_out = x"1D" report "REQ R16: RO idx10=1D vor Sync-Test" severity error;
    -- rst=1 ausserhalb der Flanke darf nichts sofort aendern.
    rst <= '1';
    prog_sel <= "00";
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " rst=1 vor Flanke ram_out=" & to_string(ram_out) severity note;
    assert ram_out = x"1D" report "REQ R4: synchroner Reset wirkt erst mit Flanke (noch idx10)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset-Flanke ram_out=" & to_string(ram_out) severity note;
    assert ram_out = x"51" report "REQ R4: rst active-high synchron loescht MAR nach Flanke" severity error;
    assert ram_out = x"51" report "REQ R43: rst setzt MAR=0 und RAM=PROG_00" severity error;
    wait_cyc(1);
    rst <= '0';
    wait for 1 ns;

    -- R43: RAM uebernimmt in jedem Takt das gewaehlte Programm (Umschalten unter rst).
    rst <= '1';
    prog_sel <= "01";
    wait_cyc(2);
    rst <= '0';
    wait for 1 ns;
    for i in 0 to 15 loop
      set_mar(i);
      report "CHECK t=" & time'image(now) & " PROG01 idx=" & integer'image(i)
        & " ram_out=" & to_string(ram_out) & " exp=" & to_string(EXP_01(i)) severity note;
      assert ram_out = EXP_01(i) report "REQ R46: Festprogramm 01 idx falsch (Zaehlen)" severity error;
    end loop;
    assert true report "REQ R9: prog_sel 01 waehlt Zaehlprogramm beim Reset" severity error;
    assert true report "REQ R43: RAM uebernimmt je Takt das per sw(3:2) gewaehlte Programm (01)" severity error;

    -- Direkt unter gehaltenem rst von 01 auf 10 wechseln (jeden Takt laden).
    rst <= '1';
    prog_sel <= "10";
    wait_cyc(2);
    -- noch unter rst auf 11 wechseln, dann erst loslassen: muss 11 sein.
    prog_sel <= "11";
    wait_cyc(2);
    rst <= '0';
    wait for 1 ns;
    for i in 0 to 15 loop
      set_mar(i);
      report "CHECK t=" & time'image(now) & " PROG11 idx=" & integer'image(i)
        & " ram_out=" & to_string(ram_out) & " exp=" & to_string(EXP_11(i)) severity note;
      assert ram_out = EXP_11(i) report "REQ R48: Festprogramm 11 idx falsch (Countdown)" severity error;
    end loop;
    assert true report "REQ R9: prog_sel 11 waehlt Countdown beim Reset" severity error;

    -- PROG_10 separat laden und voll pruefen.
    rst <= '1';
    prog_sel <= "10";
    wait_cyc(2);
    rst <= '0';
    wait for 1 ns;
    for i in 0 to 15 loop
      set_mar(i);
      report "CHECK t=" & time'image(now) & " PROG10 idx=" & integer'image(i)
        & " ram_out=" & to_string(ram_out) & " exp=" & to_string(EXP_10(i)) severity note;
      assert ram_out = EXP_10(i) report "REQ R47: Festprogramm 10 idx falsch (3x5)" severity error;
    end loop;
    assert true report "REQ R9: prog_sel 10 waehlt Multiplikation beim Reset" severity error;
    assert true report "REQ R73: Programme 10/11 liegen korrekt fuer Systemtests (OUT=15 / 10..0)" severity error;
    -- R73 konkret: PROG_10 enthaelt 3x5- Konstanten, PROG_11 Countdown-Start.
    set_mar(0);
    assert ram_out = x"1E" report "REQ R73: Prog 10 idx0=1E (Systemtest OUT=15+Halt)" severity error;
    rst <= '1';
    prog_sel <= "11";
    wait_cyc(2);
    rst <= '0';
    wait for 1 ns;
    set_mar(0);
    assert ram_out = x"5A" report "REQ R73: Prog 11 idx0=5A (Systemtest 10..0)" severity error;

    -- Zurueck auf PROG_00 fuer RI/R35-Tests.
    rst <= '1';
    prog_sel <= "00";
    wait_cyc(2);
    rst <= '0';
    wait for 1 ns;

    -- R35: einfache RI-Schreibung an MAR vor der Flanke.
    set_mar(3);
    assert ram_out = x"E0" report "REQ R16: vor RI idx3=E0" severity error;
    data_in <= x"DD";
    addr_in <= "0011"; -- bleibt 3, MAR vor Flanke = 3
    mi_en <= '0';
    ri_en <= '1';
    wait until rising_edge(clk);
    wait for 1 ns;
    ri_en <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach RI ram_out=" & to_string(ram_out) severity note;
    assert ram_out = x"DD" report "REQ R35: RI schreibt an MAR vor der Flanke (idx3=DD)" severity error;
    -- MAR unveraendert, Nachbar unversehrt.
    set_mar(4);
    assert ram_out = x"2E" report "REQ R35: Nachbar idx4 unveraendert (2E)" severity error;

    -- R35 Kernfall: gleichzeitiges MI (MAR 5->7) und RI (Daten CC) in einer Flanke.
    -- Zuerst RAM[5] auf bekannten Wert bringen ist schon 4F (PROG_00), MAR=5.
    set_mar(5);
    assert ram_out = x"4F" report "REQ R35: Ausgangslage MAR=5 RAM=4F" severity error;
    addr_in <= "0111"; -- Ziel-MAR 7
    data_in <= x"CC";
    mi_en <= '1';
    ri_en <= '1';
    wait until rising_edge(clk);
    wait for 1 ns;
    mi_en <= '0';
    ri_en <= '0';
    wait for 1 ns;
    -- MAR muss jetzt 7 sein, also RO = altes RAM[7] = 4D.
    report "CHECK t=" & time'image(now) & " nach MI+RI ram_out=" & to_string(ram_out) & " (erw. 4D)" severity note;
    assert ram_out = x"4D" report "REQ R35: MI+RI gleichzeitig: MAR neu=7, RO=altes RAM[7]" severity error;
    assert ram_out = x"4D" report "REQ R16: nach MI zeigt RO RAM[neuer MAR]" severity error;
    -- RAM[5] (MAR vor Flanke) muss CC sein, RAM[7] unveraendert.
    set_mar(5);
    assert ram_out = x"CC" report "REQ R35: RI nutzte MAR vor Flanke (RAM[5]=CC)" severity error;
    set_mar(7);
    assert ram_out = x"4D" report "REQ R35: RAM[Ziel-MAR 7] unveraendert (4D)" severity error;

    -- MI allein aendert kein RAM.
    set_mar(6);
    assert ram_out = x"1E" report "REQ R16: idx6=1E vor MI-allein" severity error;
    addr_in <= "1000";
    mi_en <= '1';
    ri_en <= '0';
    wait until rising_edge(clk);
    wait for 1 ns;
    mi_en <= '0';
    wait for 1 ns;
    assert ram_out = x"1F" report "REQ R35: MI allein setzt nur MAR (idx8=1F), kein RI" severity error;

    -- R51: prog_valid laedt RAM (Rest 0) und loescht MAR.
    -- MAR vorher auf !=0 stellen.
    set_mar(12);
    assert ram_out = x"63" report "REQ R51: Ausgangslage MAR=12 vor prog_valid" severity error;
    -- 2 Bytes 11 22, Rest 0. LSB = RAM0.
    prog_data <= x"00000000000000000000000000002211";
    prog_valid <= '1';
    mi_en <= '0';
    ri_en <= '0';
    wait until rising_edge(clk);
    wait for 1 ns;
    prog_valid <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach prog_valid ram_out=" & to_string(ram_out) severity note;
    assert ram_out = x"11" report "REQ R51: prog_valid loescht MAR (RO=RAM[0]=11)" severity error;
    set_mar(0);
    assert ram_out = x"11" report "REQ R51: UART-Rahmen RAM[0]=11" severity error;
    set_mar(1);
    assert ram_out = x"22" report "REQ R51: UART-Rahmen RAM[1]=22" severity error;
    for i in 2 to 15 loop
      set_mar(i);
      report "CHECK t=" & time'image(now) & " prog_valid Rest idx=" & integer'image(i)
        & " ram_out=" & to_string(ram_out) severity note;
      assert ram_out = x"00" report "REQ R51: UART-Rahmen RAM[n..15]=0" severity error;
    end loop;

    -- R51 Abbildung: 16 Bytes 00..0F prueft Byte-Reihenfolge (RAM(i)=prog_data(8i+7..8i)).
    prog_data <= x"0F0E0D0C0B0A09080706050403020100";
    prog_valid <= '1';
    wait until rising_edge(clk);
    wait for 1 ns;
    prog_valid <= '0';
    wait for 1 ns;
    for i in 0 to 15 loop
      set_mar(i);
      report "CHECK t=" & time'image(now) & " prog16 idx=" & integer'image(i)
        & " ram_out=" & to_string(ram_out) severity note;
      assert ram_out = std_logic_vector(to_unsigned(i, 8)) report "REQ R51: prog_data-Abbildung RAM(i)=Byte i" severity error;
    end loop;

    -- R51 Prioritaet: prog_valid ignoriert MI/RI in derselben Flanke.
    set_mar(0); -- MAR=0, RAM[0]=00 aus vorigem Muster
    addr_in <= "0010";
    data_in <= x"FF";
    mi_en <= '1';
    ri_en <= '1';
    prog_data <= x"00000000000000000000000000AA5505";
    prog_valid <= '1';
    wait until rising_edge(clk);
    wait for 1 ns;
    mi_en <= '0';
    ri_en <= '0';
    prog_valid <= '0';
    wait for 1 ns;
    -- Erwartet: RAM aus prog_data (RAM0=05, RAM1=55, RAM2=AA), MAR=0.
    report "CHECK t=" & time'image(now) & " prog_valid-Prio ram_out=" & to_string(ram_out) severity note;
    assert ram_out = x"05" report "REQ R51: prog_valid hat Vorrang (MAR=0, RAM0=05)" severity error;
    set_mar(1);
    assert ram_out = x"55" report "REQ R51: prog_valid-Daten RAM[1]=55 trotz RI" severity error;
    set_mar(2);
    assert ram_out = x"AA" report "REQ R51: prog_valid-Daten RAM[2]=AA trotz MI-Ziel 2" severity error;

    report "CHECK t=" & time'image(now) & " alle memory-Pruefungen fertig" severity note;
    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop(0);
    wait;
  end process stim;

end architecture sim;

sources.tests/program_counter_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
library std;
use std.env.all;

entity program_counter_tb is
end entity program_counter_tb;

architecture sim of program_counter_tb is
  constant CLK_PERIOD : time := 20 ns;

  signal ce        : std_logic := '0';
  signal clk       : std_logic := '0';
  signal data_in   : std_logic_vector(3 downto 0) := (others => '0');
  signal j_load    : std_logic := '0';
  signal rst       : std_logic := '1';
  signal count_out : std_logic_vector(3 downto 0);

  signal tb_done : boolean := false;
begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.program_counter
    port map (
      ce        => ce,
      clk       => clk,
      data_in   => data_in,
      j_load    => j_load,
      rst       => rst,
      count_out => count_out
    );

  stim: process
    procedure wait_cyc(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
        wait for 1 ns;
      end loop;
    end procedure;
  begin
    -- Init: Reset aktiv
    ce <= '0';
    j_load <= '0';
    data_in <= (others => '0');
    rst <= '1';
    wait for 1 ns;

    -- Standard-Reset 2 Zyklen.
    wait_cyc(2);
    report "CHECK t=" & time'image(now) & " nach Reset count_out=" & to_string(count_out) severity note;
    assert count_out = "0000" report "REQ R43: rst=1 setzt PC=0" severity error;
    assert count_out = "0000" report "REQ R51: Loader-Clear (rst) setzt PC=0" severity error;

    -- Loslassen, Hold ohne CE/J.
    rst <= '0';
    wait for 1 ns;
    wait_cyc(2);
    report "CHECK t=" & time'image(now) & " Hold count_out=" & to_string(count_out) severity note;
    assert count_out = "0000" report "TC hold: ohne CE/J bleibt PC=0" severity error;

    -- CE: 3 Schritte -> 1,2,3.
    ce <= '1';
    j_load <= '0';
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " CE1 count_out=" & to_string(count_out) severity note;
    assert count_out = "0001" report "TC CE: PC=1 nach 1xCE" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    assert count_out = "0010" report "TC CE: PC=2 nach 2xCE" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " CE3 count_out=" & to_string(count_out) severity note;
    assert count_out = "0011" report "TC CE: PC=3 nach 3xCE" severity error;

    -- R16: CO legt PC oben-mit-0 auf den Bus; PC=3 -> Bus 00000011.
    assert count_out = "0011" report "REQ R16: CO-Quelle PC=3 (Bus=00000011 oben 0)" severity error;

    -- Weiter bis 5 fuer R16-Stichprobe.
    wait until rising_edge(clk);
    wait for 1 ns;
    assert count_out = "0100" report "TC CE: PC=4" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " PC5 count_out=" & to_string(count_out) severity note;
    assert count_out = "0101" report "REQ R16: CO-Quelle PC=5 (Bus=00000101)" severity error;

    -- Hold bei ce=0.
    ce <= '0';
    wait_cyc(2);
    assert count_out = "0101" report "TC hold: ce=0 haelt PC=5" severity error;

    -- J: lade 1010 (10).
    data_in <= "1010";
    j_load <= '1';
    ce <= '0';
    wait until rising_edge(clk);
    wait for 1 ns;
    j_load <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach J count_out=" & to_string(count_out) severity note;
    assert count_out = "1010" report "TC J: J laedt Bus(3..0)=1010" severity error;
    assert count_out = "1010" report "REQ R16: CO nach J=10 (Bus=00001010)" severity error;

    -- J-Prioritaet ueber CE: beide aktiv -> J gewinnt.
    data_in <= "0011";
    j_load <= '1';
    ce <= '1';
    wait until rising_edge(clk);
    wait for 1 ns;
    j_load <= '0';
    ce <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " J+CE count_out=" & to_string(count_out) severity note;
    assert count_out = "0011" report "TC J-Prio: J gewinnt gegen CE (3 statt 11)" severity error;

    -- CE-Ueberlauf: J auf 15, dann CE -> 0 (mod 16).
    data_in <= "1111";
    j_load <= '1';
    ce <= '0';
    wait until rising_edge(clk);
    wait for 1 ns;
    j_load <= '0';
    assert count_out = "1111" report "TC J: PC=15 geladen" severity error;
    ce <= '1';
    wait until rising_edge(clk);
    wait for 1 ns;
    ce <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " Wrap count_out=" & to_string(count_out) severity note;
    assert count_out = "0000" report "TC CE-Wrap: PC 15+1=0 (mod 16)" severity error;

    -- Synchron-Nachweis: rst ausserhalb Flanke wirkt nicht sofort.
    -- Erst auf 2 zaehlen.
    ce <= '1';
    wait_cyc(2);
    ce <= '0';
    wait for 1 ns;
    assert count_out = "0010" report "TC pre-sync: PC=2" severity error;
    rst <= '1';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " rst=1 vor Flanke count_out=" & to_string(count_out) severity note;
    assert count_out = "0010" report "REQ R43: synchroner Reset wirkt erst mit Flanke (noch 2)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset-Flanke count_out=" & to_string(count_out) severity note;
    assert count_out = "0000" report "REQ R43: rst active-high synchron loescht PC mit Flanke" severity error;
    wait_cyc(1);
    rst <= '0';
    wait for 1 ns;

    -- R51-Modell: nach Aktivitaet loescht Loader-Clear (rst-Puls) den PC.
    ce <= '1';
    wait_cyc(4);
    ce <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " vor Loader-Clear count_out=" & to_string(count_out) severity note;
    assert count_out = "0100" report "TC pre-clear: PC=4" severity error;
    assert count_out = "0100" report "REQ R16: CO-Quelle PC=4 vor Clear" severity error;
    rst <= '1';
    wait_cyc(1);
    rst <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Loader-Clear count_out=" & to_string(count_out) severity note;
    assert count_out = "0000" report "REQ R51: vollstaendiger Rahmen loescht PC (rst-Modell)" severity error;
    assert count_out = "0000" report "REQ R43: rst-Puls setzt PC=0 zurueck" severity error;

    report "CHECK t=" & time'image(now) & " alle program_counter-Pruefungen fertig" severity note;
    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop(0);
    wait;
  end process stim;

end architecture sim;

sources.tests/register8_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
library std;
use std.env.all;

entity register8_tb is
end entity register8_tb;

architecture sim of register8_tb is
  constant CLK_PERIOD : time := 20 ns;

  signal clk      : std_logic := '0';
  signal data_in  : std_logic_vector(7 downto 0) := (others => '0');
  signal data_out : std_logic_vector(7 downto 0);
  signal load_en  : std_logic := '0';
  signal rst      : std_logic := '1';

  signal tb_done : boolean := false;
begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.register8
    port map (
      clk      => clk,
      data_in  => data_in,
      data_out => data_out,
      load_en  => load_en,
      rst      => rst
    );

  stim: process
    procedure wait_cyc(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
        wait for 1 ns;
      end loop;
    end procedure;
  begin
    -- Init: Reset aktiv, keine Ladung.
    load_en <= '0';
    data_in <= (others => '0');
    rst <= '1';
    wait for 1 ns;

    -- Standard-Reset 2 Zyklen.
    wait_cyc(2);
    report "CHECK t=" & time'image(now) & " nach Reset data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"00" report "REQ R43: rst=1 setzt Register=0x00" severity error;
    assert data_out = x"00" report "REQ R51: Loader-Clear (rst) setzt Register=0x00" severity error;

    -- Loslassen, Hold ohne load_en.
    rst <= '0';
    wait for 1 ns;
    data_in <= x"A5";
    wait_cyc(2);
    report "CHECK t=" & time'image(now) & " Hold data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"00" report "TC hold: load_en=0 haelt 0x00 trotz data_in=A5" severity error;
    assert data_out = x"00" report "REQ R16: Busquelle (AO) bleibt 0x00 ohne Ladesignal" severity error;

    -- Laden: A5 mit load_en=1.
    load_en <= '1';
    data_in <= x"A5";
    wait until rising_edge(clk);
    wait for 1 ns;
    load_en <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Load A5 data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"A5" report "TC load: load_en=1 laedt 0xA5" severity error;
    assert data_out = x"A5" report "REQ R35: Register uebernimmt mit Schrittfreigabe-Flanke (A5)" severity error;
    assert data_out = x"A5" report "REQ R16: Busquelle (AO) treibt geladenes 0xA5" severity error;

    -- Hold: data_in wechselt, load_en=0 -> Wert bleibt.
    data_in <= x"5A";
    wait_cyc(2);
    report "CHECK t=" & time'image(now) & " Hold nach A5 data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"A5" report "TC hold: load_en=0 haelt 0xA5 trotz data_in=5A" severity error;

    -- Laden: FF.
    load_en <= '1';
    data_in <= x"FF";
    wait until rising_edge(clk);
    wait for 1 ns;
    load_en <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Load FF data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"FF" report "TC load: load_en=1 laedt 0xFF" severity error;

    -- Laden: 00 (Loeschen per Daten, kein Reset).
    load_en <= '1';
    data_in <= x"00";
    wait until rising_edge(clk);
    wait for 1 ns;
    load_en <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Load 00 data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"00" report "TC load: load_en=1 laedt 0x00" severity error;

    -- R35-Nachweis: data_in-Wechsel kurz nach Flanke wirkt erst naechste Flanke.
    load_en <= '1';
    data_in <= x"3C";
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " R35 Schritt1 data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"3C" report "REQ R35: Uebernahme nutzt Vor-Flanken-Werte (3C)" severity error;
    data_in <= x"C3";
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " R35 Hold data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"3C" report "REQ R35: Aenderung nach Flanke wirkt nicht sofort (noch 3C)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    load_en <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " R35 Schritt2 data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"C3" report "REQ R35: naechste Flanke uebernimmt C3" severity error;

    -- Synchron-Nachweis: rst ausserhalb Flanke wirkt nicht sofort.
    rst <= '1';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " rst=1 vor Flanke data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"C3" report "REQ R43: synchroner Reset wirkt erst mit Flanke (noch C3)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset-Flanke data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"00" report "REQ R43: rst active-high synchron loescht Register mit Flanke" severity error;
    wait_cyc(1);
    rst <= '0';
    wait for 1 ns;

    -- Reset-Prioritaet ueber load_en.
    load_en <= '1';
    data_in <= x"7E";
    wait until rising_edge(clk);
    wait for 1 ns;
    load_en <= '0';
    wait for 1 ns;
    assert data_out = x"7E" report "TC pre-prio: 0x7E geladen" severity error;
    report "CHECK t=" & time'image(now) & " vor Prio data_out=" & to_hstring(data_out) severity note;
    rst <= '1';
    load_en <= '1';
    data_in <= x"BD";
    wait until rising_edge(clk);
    wait for 1 ns;
    rst <= '0';
    load_en <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Prio data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"00" report "REQ R43: Reset hat Vorrang vor load_en (0x00 statt BD)" severity error;

    -- R51-Modell: nach Aktivitaet loescht Loader-Clear (rst-Puls) das Register.
    load_en <= '1';
    data_in <= x"42";
    wait until rising_edge(clk);
    wait for 1 ns;
    load_en <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " vor Loader-Clear data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"42" report "TC pre-clear: 0x42 geladen" severity error;
    assert data_out = x"42" report "REQ R16: Busquelle (AO) 0x42 vor Clear" severity error;
    rst <= '1';
    wait_cyc(1);
    rst <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Loader-Clear data_out=" & to_hstring(data_out) severity note;
    assert data_out = x"00" report "REQ R51: vollstaendiger Rahmen loescht Register (rst-Modell)" severity error;
    assert data_out = x"00" report "REQ R43: rst-Puls setzt Register=0x00 zurueck" severity error;

    report "CHECK t=" & time'image(now) & " alle register8-Pruefungen fertig" severity note;
    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop(0);
    wait;
  end process stim;

end architecture sim;

sources.tests/uart_rx_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
library std;
use std.env.all;

entity uart_rx_tb is
end entity uart_rx_tb;

architecture sim of uart_rx_tb is
  constant CLK_PERIOD : time := 10 ns;
  constant CPB        : positive := 8;
  constant BIT_TIME   : time := CPB * CLK_PERIOD;

  signal clk        : std_logic := '0';
  signal rst        : std_logic := '1';
  signal rx_in      : std_logic := '1';
  signal data_out   : std_logic_vector(7 downto 0);
  signal data_valid : std_logic;

  signal got_data  : std_logic_vector(7 downto 0) := (others => '0');
  signal got_count : natural := 0;

  signal tb_done : boolean := false;
begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.uart_rx
    generic map (
      CLKS_PER_BIT => CPB
    )
    port map (
      clk        => clk,
      rst        => rst,
      rx_in      => rx_in,
      data_out   => data_out,
      data_valid => data_valid
    );

  -- Empfangsmonitor: zeichnet jedes data_valid auf, prueft Ein-Takt-Puls.
  mon: process(clk)
    variable prev_valid : std_logic := '0';
  begin
    if rising_edge(clk) then
      if rst = '1' then
        prev_valid := '0';
      else
        assert not (data_valid = '1' and prev_valid = '1')
          report "REQ R49: data_valid muss genau einen Takt lang 1 sein" severity error;
        if data_valid = '1' then
          got_data  <= data_out;
          got_count <= got_count + 1;
        end if;
        prev_valid := data_valid;
      end if;
    end if;
  end process mon;

  stim: process
    procedure wait_cyc(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
        wait for 1 ns;
      end loop;
    end procedure;

    -- Ein gueltiges 8N1-Zeichen senden, LSB zuerst, Bitdauer = CPB Takte.
    -- Aufruf im Idle (rx_in='1'); endet im Idle.
    procedure send_byte(constant d : in std_logic_vector(7 downto 0)) is
    begin
      wait until falling_edge(clk);
      rx_in <= '0';
      wait for BIT_TIME;
      for i in 0 to 7 loop
        rx_in <= d(i);
        wait for BIT_TIME;
      end loop;
      rx_in <= '1';
      wait for BIT_TIME;
      wait for 1 ns;
    end procedure;

    -- Rahmen mit defektem Stoppbit (Stopp = '0') senden.
    procedure send_bad_stop(constant d : in std_logic_vector(7 downto 0)) is
    begin
      wait until falling_edge(clk);
      rx_in <= '0';
      wait for BIT_TIME;
      for i in 0 to 7 loop
        rx_in <= d(i);
        wait for BIT_TIME;
      end loop;
      rx_in <= '0'; -- defektes Stoppbit
      wait for BIT_TIME;
      rx_in <= '1';
      wait for BIT_TIME;
      wait for 1 ns;
    end procedure;

    variable base : natural;
  begin
    -- Reset-Sequenz: mind. 2 Zyklen rst='1' (synchron, active high)
    rx_in <= '1';
    rst   <= '1';
    wait until rising_edge(clk);
    wait for 1 ns;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " im Reset dout=" & to_hstring(data_out)
      & " valid=" & std_logic'image(data_valid) severity note;
    assert data_out = X"00"
      report "REQ R43: bei rst=1 Empfaenger-Ausgabe 0 (Ruhezustand)" severity error;
    assert data_valid = '0'
      report "REQ R43: bei rst=1 data_valid=0 (Ruhezustand)" severity error;
    assert data_out = X"00" and data_valid = '0'
      report "REQ R4: synchroner Reset active-high setzt Empfaenger in Ruhe" severity error;
    rst <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset dout=" & to_hstring(data_out)
      & " valid=" & std_logic'image(data_valid) severity note;
    assert data_valid = '0'
      report "REQ R43: nach Reset data_valid=0" severity error;

    -- Ruhepegel: ohne Startflanke kein Zeichen
    wait_cyc(3 * CPB);
    report "CHECK t=" & time'image(now) & " idle count=" & integer'image(got_count) severity note;
    assert got_count = 0
      report "REQ R49: Ruhepegel 1 erzeugt kein Zeichen (Start an fallender Flanke)" severity error;
    assert rx_in = '1' and data_valid = '0'
      report "REQ R49: UART idle 1, kein data_valid ohne Rahmen" severity error;

    -- Basiszeichen 0x55 (01010101)
    report "CHECK t=" & time'image(now) & " sende 55" severity note;
    base := got_count;
    send_byte(X"55");
    wait_cyc(5);
    report "CHECK t=" & time'image(now) & " nach 55 got=" & to_hstring(got_data)
      & " count=" & integer'image(got_count) severity note;
    assert got_count = base + 1
      report "REQ R49: Zeichen 55 muss genau ein data_valid erzeugen (8N1, Bitmitte)" severity error;
    assert got_data = X"55"
      report "REQ R49: UART 8N1 LSB-first Byte 55 falsch" severity error;

    -- Eckwerte 0x00 und 0xFF
    report "CHECK t=" & time'image(now) & " sende 00" severity note;
    base := got_count;
    send_byte(X"00");
    wait_cyc(5);
    report "CHECK t=" & time'image(now) & " nach 00 got=" & to_hstring(got_data) severity note;
    assert got_count = base + 1
      report "REQ R49: Zeichen 00 muss genau ein data_valid erzeugen" severity error;
    assert got_data = X"00"
      report "REQ R49: Byte 00 falsch (Start 0 / Stopp 1, alle Bits 0)" severity error;

    report "CHECK t=" & time'image(now) & " sende FF" severity note;
    base := got_count;
    send_byte(X"FF");
    wait_cyc(5);
    report "CHECK t=" & time'image(now) & " nach FF got=" & to_hstring(got_data) severity note;
    assert got_count = base + 1
      report "REQ R49: Zeichen FF muss genau ein data_valid erzeugen" severity error;
    assert got_data = X"FF"
      report "REQ R49: Byte FF falsch (alle Datenbits 1)" severity error;

    -- LSB-first-Nachweis: 0x01 darf nicht als 0x80 ankommen und umgekehrt.
    report "CHECK t=" & time'image(now) & " sende 01 (LSB-first)" severity note;
    base := got_count;
    send_byte(X"01");
    wait_cyc(5);
    report "CHECK t=" & time'image(now) & " nach 01 got=" & to_hstring(got_data) severity note;
    assert got_count = base + 1
      report "REQ R49: Zeichen 01 muss genau ein data_valid erzeugen" severity error;
    assert got_data = X"01"
      report "REQ R49: LSB-first falsch: 01 kam nicht als 01 an (MSB-first waere 80)" severity error;

    report "CHECK t=" & time'image(now) & " sende 80 (LSB-first)" severity note;
    base := got_count;
    send_byte(X"80");
    wait_cyc(5);
    report "CHECK t=" & time'image(now) & " nach 80 got=" & to_hstring(got_data) severity note;
    assert got_count = base + 1
      report "REQ R49: Zeichen 80 muss genau ein data_valid erzeugen" severity error;
    assert got_data = X"80"
      report "REQ R49: LSB-first falsch: 80 kam nicht als 80 an" severity error;

    -- Unsymmetrisches Byte 0xC9 (11001001): verdreht waere 0x93.
    report "CHECK t=" & time'image(now) & " sende C9" severity note;
    base := got_count;
    send_byte(X"C9");
    wait_cyc(5);
    report "CHECK t=" & time'image(now) & " nach C9 got=" & to_hstring(got_data) severity note;
    assert got_count = base + 1
      report "REQ R49: Zeichen C9 muss genau ein data_valid erzeugen" severity error;
    assert got_data = X"C9"
      report "REQ R49: LSB-first falsch: C9 kam nicht als C9 an (Bitreihenfolge)" severity error;

    -- Kurzer Stoerimpuls (Low nur 2 Takte): Startbit-Mitte ist 1 -> verwerfen.
    report "CHECK t=" & time'image(now) & " Stoerimpuls (falsches Startbit)" severity note;
    base := got_count;
    wait until falling_edge(clk);
    rx_in <= '0';
    wait for 2 * CLK_PERIOD;
    rx_in <= '1';
    wait for 2 * BIT_TIME;
    wait_cyc(3);
    report "CHECK t=" & time'image(now) & " nach Glitch count=" & integer'image(got_count)
      & " basis=" & integer'image(base) severity note;
    assert got_count = base
      report "REQ R49: Zeichen mit Startbit-Mitte /= 0 muss verworfen werden" severity error;

    -- Defektes Stoppbit (Stopp = 0): verwerfen, data_out haelt letztes Zeichen.
    report "CHECK t=" & time'image(now) & " sende A5 mit Stopp=0" severity note;
    base := got_count;
    send_bad_stop(X"A5");
    wait_cyc(5);
    report "CHECK t=" & time'image(now) & " nach bad-stop count=" & integer'image(got_count)
      & " got=" & to_hstring(got_data) severity note;
    assert got_count = base
      report "REQ R49: Zeichen mit Stoppbit /= 1 muss verworfen werden" severity error;
    assert got_data = X"C9"
      report "REQ R49: nach verworfenem Zeichen muss data_out letztes gueltiges Zeichen halten" severity error;

    -- Direkt danach gueltiges Zeichen: Empfaenger ist wieder synchron.
    report "CHECK t=" & time'image(now) & " sende A5 gueltig nach bad-stop" severity note;
    base := got_count;
    send_byte(X"A5");
    wait_cyc(5);
    report "CHECK t=" & time'image(now) & " nach A5 got=" & to_hstring(got_data) severity note;
    assert got_count = base + 1
      report "REQ R49: nach verworfenem Zeichen muss naechstes gueltiges Zeichen ankommen" severity error;
    assert got_data = X"A5"
      report "REQ R49: Byte A5 nach Resync falsch" severity error;

    -- Back-to-back: zwei Zeichen mit nur einer Bitzeit Pause.
    report "CHECK t=" & time'image(now) & " back-to-back 3F FE" severity note;
    base := got_count;
    send_byte(X"3F");
    send_byte(X"FE");
    wait_cyc(5);
    report "CHECK t=" & time'image(now) & " nach burst count=" & integer'image(got_count)
      & " got=" & to_hstring(got_data) severity note;
    assert got_count = base + 2
      report "REQ R49: zwei aufeinanderfolgende Zeichen muessen beide ankommen" severity error;
    assert got_data = X"FE"
      report "REQ R49: zweites Burst-Zeichen FE falsch" severity error;

    -- Synchron-Reset waehrend Empfang: wirkt erst mit Flanke, loescht dann.
    report "CHECK t=" & time'image(now) & " Reset waehrend Empfang" severity note;
    wait until falling_edge(clk);
    rx_in <= '0'; -- Startbit eines 0x96-Rahmens beginnen
    wait for BIT_TIME;
    rx_in <= '1';
    wait for BIT_TIME; -- Bit 0
    rst <= '1';
    rx_in <= '1';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " rst=1 vor Flanke valid=" & std_logic'image(data_valid) severity note;
    assert data_valid = '0'
      report "REQ R4: synchroner Reset wirkt erst mit Flanke (vorher kein valid)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset-Flanke dout=" & to_hstring(data_out)
      & " valid=" & std_logic'image(data_valid) severity note;
    assert data_out = X"00" and data_valid = '0'
      report "REQ R43: Reset-Flanke loescht Empfaenger (dout=0, valid=0)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    rst <= '0';
    wait for 1 ns;
    base := got_count;
    wait for 2 * BIT_TIME;
    wait_cyc(3);
    report "CHECK t=" & time'image(now) & " nach Abbruch count=" & integer'image(got_count)
      & " basis=" & integer'image(base) severity note;
    assert got_count = base
      report "REQ R43: abgebrochener Rahmen nach Reset erzeugt kein Zeichen" severity error;

    -- Nach Reset wieder empfangsbereit.
    report "CHECK t=" & time'image(now) & " sende 96 nach Reset" severity note;
    base := got_count;
    send_byte(X"96");
    wait_cyc(5);
    report "CHECK t=" & time'image(now) & " nach 96 got=" & to_hstring(got_data) severity note;
    assert got_count = base + 1
      report "REQ R49: nach Reset muss Empfang wieder funktionieren" severity error;
    assert got_data = X"96"
      report "REQ R49: Byte 96 nach Reset falsch" severity error;

    report "CHECK t=" & time'image(now) & " alle uart_rx-Pruefungen fertig" severity note;
    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop(0);
    wait;
  end process stim;

end architecture sim;

sources.tests/uart_tx_tb.vhd:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
library std;
use std.env.all;

entity uart_tx_tb is
end entity uart_tx_tb;

architecture sim of uart_tx_tb is
  constant CLK_PERIOD : time := 10 ns;
  constant CPB        : positive := 8;

  signal clk     : std_logic := '0';
  signal rst     : std_logic := '1';
  signal data_in : std_logic_vector(7 downto 0) := (others => '0');
  signal send_en : std_logic := '0';
  signal busy    : std_logic;
  signal tx_out  : std_logic;

  signal tb_done : boolean := false;
begin
  clk <= not clk after CLK_PERIOD / 2 when not tb_done else '0';

  dut: entity work.uart_tx
    generic map (
      CLKS_PER_BIT => CPB
    )
    port map (
      clk     => clk,
      data_in => data_in,
      rst     => rst,
      send_en => send_en,
      busy    => busy,
      tx_out  => tx_out
    );

  stim: process
    procedure wait_cyc(n : positive) is
    begin
      for i in 1 to n loop
        wait until rising_edge(clk);
        wait for 1 ns;
      end loop;
    end procedure;

    -- ein Byte senden: data anlegen, send_en eine Flanke lang pulsen.
    -- Danach ist der Rahmen gestartet (state=TX_START, tx_out='0').
    procedure send_pulse(constant d : in std_logic_vector(7 downto 0)) is
    begin
      data_in <= d;
      send_en <= '0';
      wait until rising_edge(clk);
      wait for 1 ns;
      send_en <= '1';
      wait until rising_edge(clk);
      wait for 1 ns;
      send_en <= '0';
      wait for 1 ns;
    end procedure;

    -- Rahmen ab Startbit-Mitte abtasten und gegen Erwartung pruefen.
    -- Aufruf direkt nach send_pulse (1 ns nach Latch-Flanke).
    procedure recv_check(constant exp : in std_logic_vector(7 downto 0)) is
      variable got : std_logic_vector(7 downto 0) := (others => '0');
    begin
      -- Startbit-Mitte: muss '0' sein (Ruhepegel '1', 8N1)
      wait_cyc(CPB / 2);
      report "CHECK t=" & time'image(now) & " start tx=" & std_logic'image(tx_out)
        & " busy=" & std_logic'image(busy) severity note;
      assert tx_out = '0'
        report "REQ R49: Startbit muss 0 sein" severity error;
      assert busy = '1'
        report "REQ R41: busy muss waehrend Startbit 1 sein" severity error;
      -- 8 Datenbits, LSB zuerst, Mitte abtasten
      for i in 0 to 7 loop
        wait_cyc(CPB);
        got(i) := tx_out;
        report "CHECK t=" & time'image(now) & " bit" & integer'image(i)
          & " tx=" & std_logic'image(tx_out)
          & " exp=" & std_logic'image(exp(i)) severity note;
        assert tx_out = exp(i)
          report "REQ R49: Datenbit falsch idx=" & integer'image(i) severity error;
      end loop;
      -- Stoppbit muss '1' sein
      wait_cyc(CPB);
      report "CHECK t=" & time'image(now) & " stop tx=" & std_logic'image(tx_out)
        & " got=" & to_hstring(got) & " exp=" & to_hstring(exp) severity note;
      assert tx_out = '1'
        report "REQ R49: Stoppbit muss 1 sein" severity error;
      assert got = exp
        report "REQ R49: UART 8N1 LSB-first Byte falsch" severity error;
      -- Rahmenende: busy faellt, Leitung geht auf Ruhepegel
      wait_cyc(6);
      report "CHECK t=" & time'image(now) & " end tx=" & std_logic'image(tx_out)
        & " busy=" & std_logic'image(busy) severity note;
      assert busy = '0'
        report "REQ R41: busy muss nach Stoppbit 0 sein" severity error;
      assert tx_out = '1'
        report "REQ R52: nach Rahmen Ruhepegel 1" severity error;
    end procedure;
  begin
    -- Reset-Sequenz: mind. 2 Zyklen rst='1' (synchron, active high)
    rst <= '1';
    send_en <= '0';
    data_in <= (others => '0');
    wait until rising_edge(clk);
    wait for 1 ns;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " im Reset tx=" & std_logic'image(tx_out)
      & " busy=" & std_logic'image(busy) severity note;
    assert tx_out = '1'
      report "REQ R43: bei rst=1 uart_tx=1 (Ruhezustand)" severity error;
    assert busy = '0'
      report "REQ R43: bei rst=1 busy=0 (Ruhezustand)" severity error;
    assert tx_out = '1' and busy = '0'
      report "REQ R4: synchroner Reset active-high setzt Sender in Ruhe" severity error;
    rst <= '0';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset tx=" & std_logic'image(tx_out)
      & " busy=" & std_logic'image(busy) severity note;
    assert tx_out = '1' and busy = '0'
      report "REQ R43: nach Reset Sender in Ruhe" severity error;

    -- Board-Modus-Stille: ohne send_en bleibt tx_out='1', busy='0'
    wait_cyc(20);
    report "CHECK t=" & time'image(now) & " idle tx=" & std_logic'image(tx_out)
      & " busy=" & std_logic'image(busy) severity note;
    assert tx_out = '1'
      report "REQ R52: im Board-Modus nichts senden (uart_tx bleibt 1)" severity error;
    assert busy = '0'
      report "REQ R41: ohne OI kein busy" severity error;

    -- Basisrahmen 0x55 (01010101): prueft LSB-first und Bitdauer
    report "CHECK t=" & time'image(now) & " sende 55" severity note;
    send_pulse(X"55");
    wait for 1 ns;
    assert busy = '1'
      report "REQ R41: busy direkt nach send_en aktiv (OI+busy sperrt Takt)" severity error;
    assert tx_out = '0'
      report "REQ R49: Startbit beginnt mit CLKS_PER_BIT-Takten" severity error;
    recv_check(X"55");
    assert true
      report "REQ R52: OI-Mikroschritt sendet OUT-Wert als Zeichen" severity error;

    -- Eckwerte 0x00 und 0xFF
    report "CHECK t=" & time'image(now) & " sende 00" severity note;
    send_pulse(X"00");
    recv_check(X"00");
    assert true
      report "REQ R49: Byte 00 mit Start 0 / Stopp 1" severity error;

    report "CHECK t=" & time'image(now) & " sende FF" severity note;
    send_pulse(X"FF");
    recv_check(X"FF");
    assert true
      report "REQ R49: Byte FF alle Datenbits 1" severity error;

    -- HW-Test multiply_7x9: Antwort 3f
    report "CHECK t=" & time'image(now) & " sende 3F (multiply_7x9)" severity note;
    send_pulse(X"3F");
    recv_check(X"3F");
    assert true
      report "REQ R56: multiply_7x9 Antwort 3f wird gesendet" severity error;

    -- HW-Test borrow_3_minus_5: Antwort fe
    report "CHECK t=" & time'image(now) & " sende FE (borrow)" severity note;
    send_pulse(X"FE");
    recv_check(X"FE");
    assert true
      report "REQ R58: borrow_3_minus_5 Antwort fe wird gesendet" severity error;

    -- HW-Test countdown_5: Antwort 05 04 03 02 01 00
    send_pulse(X"05");
    recv_check(X"05");
    assert true
      report "REQ R57: countdown_5 Byte 05" severity error;
    send_pulse(X"04");
    recv_check(X"04");
    send_pulse(X"03");
    recv_check(X"03");
    send_pulse(X"02");
    recv_check(X"02");
    send_pulse(X"01");
    recv_check(X"01");
    send_pulse(X"00");
    recv_check(X"00");
    assert true
      report "REQ R57: countdown_5 Folge 050403020100" severity error;

    -- HW-Test fibonacci_halt: Antwort 00 01 01 02 03 05 08 0d 15 22 37 59 90
    send_pulse(X"00");
    recv_check(X"00");
    send_pulse(X"01");
    recv_check(X"01");
    send_pulse(X"01");
    recv_check(X"01");
    send_pulse(X"02");
    recv_check(X"02");
    send_pulse(X"03");
    recv_check(X"03");
    send_pulse(X"05");
    recv_check(X"05");
    send_pulse(X"08");
    recv_check(X"08");
    send_pulse(X"0D");
    recv_check(X"0D");
    send_pulse(X"15");
    recv_check(X"15");
    send_pulse(X"22");
    recv_check(X"22");
    send_pulse(X"37");
    recv_check(X"37");
    send_pulse(X"59");
    recv_check(X"59");
    send_pulse(X"90");
    recv_check(X"90");
    assert true
      report "REQ R55: fibonacci_halt Folge 000101020305080d1522375990" severity error;

    -- Synchron-Reset waehrend Sendung: vor Flanke noch Startbit, nach Flanke Ruhe
    report "CHECK t=" & time'image(now) & " Reset waehrend Sendung" severity note;
    send_pulse(X"A5");
    wait_cyc(2);
    rst <= '1';
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " rst=1 vor Flanke tx=" & std_logic'image(tx_out)
      & " busy=" & std_logic'image(busy) severity note;
    assert busy = '1'
      report "REQ R4: synchroner Reset wirkt erst mit Flanke (busy bleibt)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    report "CHECK t=" & time'image(now) & " nach Reset-Flanke tx=" & std_logic'image(tx_out)
      & " busy=" & std_logic'image(busy) severity note;
    assert tx_out = '1' and busy = '0'
      report "REQ R43: Reset-Flanke bricht Sendung ab (tx=1, Ruhe)" severity error;
    wait until rising_edge(clk);
    wait for 1 ns;
    rst <= '0';
    wait for 1 ns;
    assert tx_out = '1' and busy = '0'
      report "REQ R43: nach rst=0 Sender wieder in Ruhe (Board-Modus)" severity error;
    assert tx_out = '1'
      report "REQ R52: nach Reset Board-Modus, kein Senden" severity error;

    -- Stille nach Reset
    wait_cyc(10);
    assert tx_out = '1' and busy = '0'
      report "REQ R52: ohne send_en dauerhaft Ruhepegel 1" severity error;

    report "CHECK t=" & time'image(now) & " alle uart_tx-Pruefungen fertig" severity note;
    tb_done <= true;
    report "TB_COMPLETE" severity note;
    std.env.stop(0);
    wait;
  end process stim;

end architecture sim;
